// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import {IOFT, SendParam} from "@layerzerolabs/oft-evm/contracts/interfaces/IOFT.sol";
import {IOAppCore} from "@layerzerolabs/oapp-evm/contracts/oapp/interfaces/IOAppCore.sol";
import {MessagingFee, MessagingReceipt} from "@layerzerolabs/oapp-evm/contracts/oapp/OAppSender.sol";
import {IMorphoLoanSubaccountRemote} from "../../userInterfaces/IMorphoLoanSubaccountRemote.sol";
import {
    ACTION_BORROW,
    ACTION_WITHDRAW,
    ACTION_DEPOSIT_COLLATERAL,
    ACTION_CANCEL,
    ACTION_REDEEM_HOME,
    DESTINATION_KIND_EVM
} from "../../userInterfaces/ILoanSubaccount.sol";
import {IComposeTransportFacet} from "../../userInterfaces/facets/IComposeTransportFacet.sol";
import {IMorphoLoanMarketsFacet} from "../../userInterfaces/facets/IMorphoLoanMarketsFacet.sol";
import {PAYLOAD_VERSION_1} from "../../userInterfaces/IComposeReceiverAccountBase.sol";
import {IPauseFacet} from "../../userInterfaces/facets/IPauseFacet.sol";
import {IMorpho} from "../interface/IMorpho.sol";
import {IIrm} from "../interface/IIrm.sol";
import {IOracle} from "../interface/IOracle.sol";
import {MorphoMath} from "../library/MorphoMath.sol";
import {LoanMath} from "../library/LoanMath.sol";
import {SubaccountBase} from "./SubaccountBase.sol";
import {ComposeReceiverAccountBase} from "./ComposeReceiverAccountBase.sol";

/**
 * @title MorphoLoanSubaccountRemote contract
 * @notice The loan-chain-side subaccount implementation (Ethereum, at launch): same frozen
 * proxy and CREATE2 address as the Flare-side account, resolved per type through the
 * controller-as-beacon. Authenticated compose actions ({ComposeReceiverAccountBase}), sent by
 * this same account on Flare, operate on its type's write-once Morpho market - so the address
 * itself commits to the pool. Repayment, idle-collateral deposit and the fee checkpoint are
 * permissionless fixed rails, and nothing here is parent-callable: Morpho collateral and debt
 * move only behind the compose authentication. Idle FXRP has
 * one route, into the position ({depositIdleFxrp}), from where the signed withdraw action
 * brings it home under the position's ordinary conditions. Across the rails and the signed
 * actions every destination is fixed on-chain - the account's own position, the parent, the
 * governance-set fee recipient, or (the withdraw's return leg) this account's own address on
 * Flare - so no caller ever
 * chooses a destination, a market or an amount source. The one user-chosen destination is a
 * signed borrow's disbursement, authorized by the XRPL signature its payload carries.
 * @dev No native rail: the only protocol-delivered native is a withdraw delivery's compose
 * value (the return leg's fee), spent or forwarded to the parent within the same call, so a
 * plain send reverts; native landing without a call (pre-deployment funding, an LZ native
 * drop, a force-send) strands until a beacon upgrade adds a rail - accepted.
 */
contract MorphoLoanSubaccountRemote is IMorphoLoanSubaccountRemote, SubaccountBase, ComposeReceiverAccountBase {
    using SafeERC20 for IERC20;

    /// @dev The market's borrow side brought to the current block, and this account's position
    /// on it, as the read surface needs them: the accrued totals, the pool's remaining liquidity,
    /// the account's shares, collateral and live debt.
    struct MarketView {
        uint256 shares;
        uint256 collateral;
        uint256 totalBorrowAssets;
        uint256 totalBorrowShares;
        uint256 liquidity;
        uint256 debt;
    }

    /// @dev WAD fixed point, the fee carry's precision (the fee formulas themselves live in
    /// {LoanMath}, shared with the read surface).
    uint256 private constant WAD = LoanMath.WAD;
    /// @dev Morpho's oracle scale: `loanAmount = mulDiv(collateralAmount, price, 1e36)`.
    uint256 private constant ORACLE_PRICE_SCALE = 1e36;

    // this lineage's own linear state starts right after ControlledAccountBase's slot 0 (the
    // bases' other state is namespaced): the canonical principal at the last checkpoint, the
    // WAD fee carry, and the checkpoint clock and rate snapshot the next period is priced at
    uint256 private feePrincipal;
    uint256 private flareDebtX18;
    uint64 private feeLastCheckpoint;
    uint64 private feeSnapshotFloor;
    uint64 private feeSnapshotSpread;
    // the borrow shares the principal was recorded with, and the collateral the position should
    // hold unless something else touched it - recorded with the principal, then moved by the
    // account's own deposits and withdrawals - so the next checkpoint can tell a liquidation from
    // a repayment outside the rails; zero on an account older than the fields
    uint128 private feeBaseShares;
    uint128 private feeBaseCollateral;

    // deliberately no receive() and no native exit: a withdraw delivery's compose value is
    // spent or forwarded in-call; pre-deployment, dropped or force-sent native strands

    /// @inheritdoc IMorphoLoanSubaccountRemote
    function repay()
        external
        nonReentrant
        returns (uint256 _assets)
    {
        // no pause gate: repaying moves the position toward safety, and must stay available
        IMorphoLoanMarketsFacet.Market memory market = _myMarket();
        IERC20 loanToken = IERC20(market.marketParams.loanToken);
        uint256 balance = loanToken.balanceOf(address(this));
        require(balance > 0, NothingToRepay());

        // fee checkpoint before, re-sync after. Shares first: the debt-free paths must not
        // depend on accrual (a reverting IRM must not trap recoverable tokens)
        _checkpointFee(market);
        if (_borrowSharesOf(market) > 0) {
            // accrue first, so the clamp compares against the live debt (idempotent after
            // the checkpoint's accrual)
            IMorpho(market.morpho).accrueInterest(market.marketParams);
            (uint128 borrowShares, uint256 fullDebt) = _debtOf(market);
            uint256 collectible = flareDebtX18 / WAD;
            if (balance < fullDebt + collectible) {
                // a payment short of debt plus fee is split pro rata between the two: the
                // fee's share (rounded down, the remainder to the debt) is paid first,
                // best-effort - refused by the token (a frozen recipient), it stays in the
                // balance and repays debt (if that closes the debt, the tail below retries
                // the remainder and reserves what still cannot be paid); what the tail
                // cannot pay either stays owed
                uint256 feeShare = LoanMath.feeShare(balance, fullDebt, collectible);
                if (feeShare > 0) {
                    address recipient = _feeRecipient();
                    uint256 paid = _payFee(loanToken, recipient, feeShare);
                    if (paid == 0) {
                        emit LoanFeeDeferred(recipient, feeShare);
                    }
                    balance -= paid;
                }
            }
            if (balance >= fullDebt) {
                // the balance covers the whole debt (from the split when the paid share's
                // round-down leaves exactly the debt, or when a deferred share leaves the
                // full payment available): close by exact borrow shares (no over-repay
                // revert) - Morpho pulls exactly the debt, the tail handles any remainder
                loanToken.forceApprove(market.morpho, fullDebt);
                (_assets, ) = IMorpho(market.morpho).repay(
                    market.marketParams, 0, borrowShares, address(this), ""
                );
            } else {
                loanToken.forceApprove(market.morpho, balance);
                (_assets, ) = IMorpho(market.morpho).repay(
                    market.marketParams, balance, 0, address(this), ""
                );
            }
            loanToken.forceApprove(market.morpho, 0);
            _syncFeePrincipal(market);
            emit LoanRepaid(_parentAccount(), _assets);
        }

        _collectFeeAndPushSurplus(market, loanToken);
    }

    /// @inheritdoc IMorphoLoanSubaccountRemote
    function checkpointFee()
        external
        nonReentrant
    {
        // permissionless, pause-exempt: also the liquidated account's relief (the floor
        // accrues on the stale principal until someone checkpoints)
        _checkpointFee(_myMarket());
    }

    /// @inheritdoc IMorphoLoanSubaccountRemote
    function depositIdleFxrp()
        external
        nonReentrant
        returns (uint256 _amount)
    {
        IMorphoLoanMarketsFacet.Market memory market = _myMarket();
        _checkDepositAllowed(market);
        // with a loan the period settles first, so a deposit after a liquidation ends its credit
        if (feePrincipal != 0) {
            _checkpointFee(market);
        }
        _amount = _supplyBalance(market);
        require(_amount > 0, NothingToDeposit());
        emit IdleFxrpDeposited(_parentAccount(), _amount);
    }

    /// @inheritdoc IMorphoLoanSubaccountRemote
    function getLoanFeeState()
        external view
        returns (
            uint256 _principal,
            uint256 _feeDebtX18,
            uint256 _collectible,
            uint64 _lastCheckpoint,
            uint64 _feeFloor,
            uint64 _feeSpread
        )
    {
        return (
            feePrincipal,
            flareDebtX18,
            flareDebtX18 / WAD,
            feeLastCheckpoint,
            feeSnapshotFloor,
            feeSnapshotSpread
        );
    }

    /// @inheritdoc IMorphoLoanSubaccountRemote
    function getLoanPosition()
        external view
        returns (LoanPosition memory _position)
    {
        IMorphoLoanMarketsFacet.Market memory market = _myMarket();
        MarketView memory view_ = _marketView(market);
        _position.collateral = view_.collateral;
        _position.idleCollateral = IERC20(market.marketParams.collateralToken).balanceOf(address(this));
        _position.idleLoanToken = IERC20(market.marketParams.loanToken).balanceOf(address(this));
        _position.debt = view_.debt;
        _position.feeDebtX18 = _projectedFeeX18(market, view_);
        _position.oraclePrice = _oraclePrice(market);
        _position.collateralValue =
            Math.mulDiv(view_.collateral, _position.oraclePrice, ORACLE_PRICE_SCALE);
        _position.lltv = market.marketParams.lltv;
        _position.requiredCover =
            LoanMath.requiredCover(view_.debt, _position.feeDebtX18 / WAD, market.marketParams.lltv);
        _position.morphoHealthFactor = view_.debt == 0
            ? type(uint256).max
            : Math.mulDiv(Math.mulDiv(_position.collateralValue, market.marketParams.lltv, WAD), WAD, view_.debt);
        _position.liquidationPrice = _liquidationPrice(view_.debt, view_.collateral, market.marketParams.lltv);
    }

    /// @inheritdoc IMorphoLoanSubaccountRemote
    function getLoanLimits(
        uint256 _additionalCollateral
    )
        external view
        returns (LoanLimits memory _limits)
    {
        IMorphoLoanMarketsFacet.Market memory market = _myMarket();
        MarketView memory view_ = _marketView(market);
        uint256 collectible = _projectedFeeX18(market, view_) / WAD;
        uint256 price = _oraclePrice(market);
        _limits.marketLiquidity = view_.liquidity;
        _limits.maxWithdraw = _maxWithdraw(view_, collectible, price, market.marketParams.lltv);
        uint256 supplied = view_.collateral
            + IERC20(market.marketParams.collateralToken).balanceOf(address(this))
            + _additionalCollateral;
        _limits.maxBorrowByCover = _maxBorrow(
            view_, collectible, Math.mulDiv(supplied, price, ORACLE_PRICE_SCALE), market.marketParams.lltv
        );
    }

    /// @inheritdoc IMorphoLoanSubaccountRemote
    function previewRepay(
        uint256 _additionalLoanToken
    )
        external view
        returns (RepayPreview memory _preview)
    {
        IMorphoLoanMarketsFacet.Market memory market = _myMarket();
        // shares-first, as repay is: a debt-free account's preview reads no rate model, so it
        // stays available where repay does - the fee-only settlement and the surplus recovery
        // of an account whose market's IRM has died
        MarketView memory view_;
        if (_borrowSharesOf(market) != 0) {
            view_ = _marketView(market);
        }
        uint256 collectible = _projectedFeeX18(market, view_) / WAD;
        uint256 idle = IERC20(market.marketParams.loanToken).balanceOf(address(this));
        _preview = _simulateRepay(view_, collectible, idle + _additionalLoanToken);
        uint256 owed = view_.debt + collectible;
        _preview.closingTopUp = owed > idle ? owed - idle : 0;
    }

    /// @inheritdoc IMorphoLoanSubaccountRemote
    function previewWithdraw(
        uint256 _amount
    )
        external view
        returns (WithdrawPreview memory _preview)
    {
        IMorphoLoanMarketsFacet.Market memory market = _myMarket();
        MarketView memory view_ = _marketView(market);
        uint256 collectible = _projectedFeeX18(market, view_) / WAD;
        uint256 lltv = market.marketParams.lltv;
        _preview.requiredCover = LoanMath.requiredCover(view_.debt, collectible, lltv);
        _preview.remainingValue = _remainingValue(view_.collateral, _amount, _oraclePrice(market));
        _preview.coverSatisfied =
            _preview.requiredCover == 0 || _preview.remainingValue >= _preview.requiredCover;
        if (!_preview.coverSatisfied) {
            uint256 idle = IERC20(market.marketParams.loanToken).balanceOf(address(this));
            _preview.minimumTopUp = _minimumTopUp(view_, collectible, idle, _preview.remainingValue, lltv);
        }
    }

    /// @inheritdoc IMorphoLoanSubaccountRemote
    function previewBorrow(
        uint256 _amount,
        uint256 _additionalCollateral
    )
        external view
        returns (BorrowPreview memory _preview)
    {
        IMorphoLoanMarketsFacet.Market memory market = _myMarket();
        MarketView memory view_ = _marketView(market);
        uint256 supplied = view_.collateral
            + IERC20(market.marketParams.collateralToken).balanceOf(address(this))
            + _additionalCollateral;
        _preview.collateralValue = Math.mulDiv(supplied, _oraclePrice(market), ORACLE_PRICE_SCALE);
        _preview.debtAfter = _debtAfterBorrow(view_, _amount);
        _preview.requiredCover = LoanMath.requiredCover(
            _preview.debtAfter, _projectedFeeX18(market, view_) / WAD, market.marketParams.lltv
        );
        _preview.coverSatisfied = _preview.collateralValue >= _preview.requiredCover;
        _preview.marketLiquidity = view_.liquidity;
    }

    /// @dev The subaccount's action set (see {ComposeReceiverAccountBase._dispatch}).
    function _dispatch(
        uint8 _action,
        bytes memory _actionData,
        bytes32 _guid,
        uint256 _amountLD
    )
        internal override
    {
        if (_action == ACTION_BORROW) {
            _executeBorrow(_actionData, _guid);
        } else if (_action == ACTION_WITHDRAW) {
            _executeWithdraw(_actionData, _guid);
        } else if (_action == ACTION_DEPOSIT_COLLATERAL) {
            _executeDepositCollateral(_guid, _amountLD);
        } else if (_action == ACTION_CANCEL) {
            _executeCancel(_actionData, _guid);
        } else {
            revert UnsupportedAction(_action);
        }
    }

    /// @dev The withdraw action spends compose value in the same call - the return leg's
    /// LayerZero fee, with the excess pushed to the parent - so it opts in; every
    /// other action must not carry value (a mistaken delivery stays retriable without it).
    /// @dev Adding `ACTION_BORROW` here is what enables a destination kind that pays for its own
    /// onward delivery, and it must account for the native in three places, not one: a
    /// SUCCESSFUL EVM disbursement would then be allowed to carry value it never spends (this
    /// path leaves native untouched, and the account has no rail to recover it, so that value
    /// must be refused or refunded), a terminal skip already sweeps to the parent, and whatever
    /// the onward delivery leaves unspent must go the same way.
    function _acceptsComposeValue(
        uint8 _action
    )
        internal pure override
        returns (bool)
    {
        return _action == ACTION_WITHDRAW;
    }

    /// @dev Consumes an operation id so the borrow or withdraw packet carrying it can never
    /// execute. Deliberately minimal: no pause check (revoking an authority is not new
    /// exposure), no deadline (a late cancellation is unnecessary or still correct), no market
    /// or terms read, nothing moved. An id already consumed - the original executed first, or
    /// this cancellation was delivered twice - finalizes without an event rather than
    /// reverting, so a lost race cannot leave the packet retriable forever.
    function _executeCancel(
        bytes memory _actionData,
        bytes32 _guid
    )
        private
    {
        bytes32 operationId = abi.decode(_actionData, (bytes32));
        require(operationId != bytes32(0), InvalidOperationId());
        if (_operationUsed(operationId)) {
            return;
        }
        _markOperationUsed(operationId);
        emit LoanActionCancelled(_parentAccount(), operationId, _guid);
    }

    /// @dev Supplies the whole idle FXRP balance (if any) as collateral and borrows on the
    /// type's market, disbursing to the destination. Temporary debt gates revert rather than
    /// skip, so the packet stays retriable.
    function _executeBorrow(
        bytes memory _actionData,
        bytes32 _guid
    )
        private
    {
        (
            bytes32 operationId,
            uint64 deadline,
            uint8 destinationKind,
            bytes32 destination,
            uint256 borrowAmount,
            uint256 minComposeValue
        ) = abi.decode(_actionData, (bytes32, uint64, uint8, bytes32, uint256, uint256));
        require(borrowAmount > 0, ZeroAmount());
        require(operationId != bytes32(0), InvalidOperationId());
        // the floor is reserved for a kind that pays for its own onward delivery; the EVM
        // disbursement spends nothing here, so naming one is a malformed instruction (the
        // Flare sender refuses it too, before the bridge fee)
        if (destinationKind == DESTINATION_KIND_EVM) {
            require(minComposeValue == 0, UnexpectedDeliveryValueFloor());
        }
        // the signed delivery floor comes before every consuming branch, as in the withdraw:
        // delivery is permissionless and the value unauthenticated, so a below-floor delivery
        // must revert and stay retriable rather than consume the packet with the prepaid value
        // undelivered. No kind V1 supports carries value, so today this can only refuse a
        // packet naming a floor for a kind that is unsupported anyway
        require(msg.value >= minComposeValue, InsufficientDeliveryValue(minComposeValue));
        // terminal gates come first, so a duplicate or expired delivery finalizes even when
        // borrowing is disabled or the market is not yet registered, instead of reverting
        // forever; its value must not strand on an account with no native rail
        if (_skipped(operationId, deadline, _guid)) {
            _sweepValueToParent(msg.value);
            return;
        }
        // a debt increase respects the pause and the per-type borrow switch
        _checkNotPaused();
        require(
            !IMorphoLoanMarketsFacet(controllerAddress).isLoanBorrowingDisabled(_accountType()),
            BorrowingDisabled()
        );
        // and configured fee terms (the recipient is the activation marker); a revert, not
        // a skip, so the packet stays retriable
        require(
            IMorphoLoanMarketsFacet(controllerAddress).getLoanFeeTerms(_accountType()).feeRecipient != address(0),
            FeeTermsNotConfigured()
        );
        _markOperationUsed(operationId);

        IMorphoLoanMarketsFacet.Market memory market = _myMarket();
        uint256 supplied = _supplyBalance(market);
        _borrowTo(market, destinationKind, destination, borrowAmount);
        emit LoanOpened(
            _parentAccount(),
            operationId,
            supplied,
            borrowAmount,
            destinationKind,
            destination,
            _guid
        );
    }

    /// @dev Supplies the whole idle FXRP balance as collateral - the authenticated bridged
    /// amount and any residue - without changing debt. The action carries no operation id and
    /// no deadline: a deposit only adds the user's own collateral, which the permissionless
    /// rail can do with the same tokens anyway, so a re-issued one (a new packet - a delivered
    /// compose cannot replay) deposits again and a late one
    /// is harmless (the same reasoning that leaves the Flare redeem-home id-less). During a
    /// pause only an indebted position may receive it - defending stays available, new
    /// exposure waits - and a temporary rejection reverts, leaving the packet retriable.
    function _executeDepositCollateral(
        bytes32 _guid,
        uint256 _bridgedAmount
    )
        private
    {
        require(_bridgedAmount > 0, ZeroAmount());
        IMorphoLoanMarketsFacet.Market memory market = _myMarket();
        _checkDepositAllowed(market);
        // settles the period first, as {depositIdleFxrp} does
        if (feePrincipal != 0) {
            _checkpointFee(market);
        }
        // the credit already sits on the account (the OFT delivered it a transaction ago), so
        // it goes in with whatever else is here; the rail may already have deposited it (the
        // accepted race), in which case nothing is left to supply and that is fine
        uint256 supplied = _supplyBalance(market);
        emit CollateralDeposited(_parentAccount(), supplied, _guid);
    }

    /// @dev Supplies the account's whole FXRP balance as collateral and returns the amount, zero
    /// when nothing is here. Every FXRP on this account is the user's own and has one route, the
    /// position: a packet's freshly delivered credit, a skipped packet's credit, a direct send -
    /// there is no distinction to draw, so all of it goes in. The permissionless rail may have
    /// put a credit into the position before its packet is delivered (the accepted race),
    /// leaving nothing to supply; a message-only borrow arrives with nothing idle by design.
    function _supplyBalance(
        IMorphoLoanMarketsFacet.Market memory _market
    )
        private
        returns (uint256 _supplied)
    {
        IERC20 fxrp = IERC20(_market.marketParams.collateralToken);
        _supplied = fxrp.balanceOf(address(this));
        if (_supplied > 0) {
            fxrp.forceApprove(_market.morpho, _supplied);
            IMorpho(_market.morpho).supplyCollateral(
                _market.marketParams, _supplied, address(this), ""
            );
            fxrp.forceApprove(_market.morpho, 0);
            // a delta, never the position's collateral: re-reading that would erase a liquidation
            // earlier in the period
            feeBaseCollateral += SafeCast.toUint128(_supplied);
        }
    }

    /// @dev Borrows `_amount` on the position as it stands and sends it to the destination.
    /// The fee is checkpointed before and its principal re-synced after (an unsynced new
    /// principal would read as market interest at the next checkpoint), and the cover gate runs
    /// on the resulting position before anything leaves: a borrow past it reverts, retriably,
    /// with nothing sent. Morpho's own health check ran inside the borrow; the gate implies
    /// it, so it is the binding one whenever Morpho passed.
    function _borrowTo(
        IMorphoLoanMarketsFacet.Market memory _market,
        uint8 _destinationKind,
        bytes32 _destination,
        uint256 _amount
    )
        private
    {
        // only the EVM/ERC-20 form is implemented; the Wormhole-to-XRPL kind is reserved
        require(
            _destinationKind == DESTINATION_KIND_EVM,
            UnsupportedDestinationKind(_destinationKind)
        );
        // a clean zero-padded, non-zero EVM address that is not this account (the proceeds
        // could only repay the new debt); the parent Personal Account - the user's own
        // compose-driven account on this chain - is a valid target
        address destinationAddress = address(uint160(uint256(_destination)));
        require(
            uint256(_destination) >> 160 == 0 &&
                destinationAddress != address(0) &&
                destinationAddress != address(this),
            InvalidDestination()
        );
        _checkpointFee(_market);
        (uint256 assetsBorrowed, ) = IMorpho(_market.morpho).borrow(
            _market.marketParams, _amount, 0, address(this), address(this)
        );
        _syncFeePrincipal(_market);
        _requirePositionCovered(_market, 0);
        IERC20(_market.marketParams.loanToken).safeTransfer(destinationAddress, assetsBorrowed);
    }

    /// @dev The atomic withdrawal: withdraws collateral and bridges the withdrawn amount home
    /// with the redeem-home compose in the same execution - no idle window, so the redeposit race
    /// cannot touch a withdrawal. The delivered compose value pays the return leg's live quote
    /// against the signed `returnOptions`, with the excess to the parent; too little value or
    /// any other failure reverts and leaves the delivery retriable. Morpho enforces position
    /// health.
    function _executeWithdraw(
        bytes memory _actionData,
        bytes32 _guid
    )
        private
    {
        (
            bytes32 operationId,
            uint64 deadline,
            uint256 amount,
            uint256 minAmount,
            uint256 minComposeValue,
            bytes memory returnOptions
        ) = abi.decode(_actionData, (bytes32, uint64, uint256, uint256, uint256, bytes));
        require(amount > 0, ZeroAmount());
        require(operationId != bytes32(0), InvalidOperationId());
        // the arrival floor the sender signed for the return leg: the adapter is fee-capable
        // and this quote happens after the instruction was signed, so the allowance travels
        // with it rather than being read here
        require(
            minAmount > 0 && minAmount <= amount,
            InvalidMinAmountReceived(amount, minAmount)
        );
        // the signed delivery floor comes before every consuming branch: delivery is
        // permissionless and the value unauthenticated, so a below-floor delivery (a
        // zero-value front-run of an expiring packet, say) must revert and stay retriable
        // rather than consume the packet with the prepaid value undelivered
        require(msg.value >= minComposeValue, InsufficientDeliveryValue(minComposeValue));
        // terminal gates next, so a duplicate or expired delivery finalizes even when
        // the market is not yet registered, instead of reverting forever; its value must not
        // strand on an account with no native rail
        if (_skipped(operationId, deadline, _guid)) {
            _sweepValueToParent(msg.value);
            return;
        }
        // pause after the terminal gates (duplicates and expired packets finalize during a
        // pause); the exit itself waits - it rides the OFT
        _checkNotPaused();
        IMorphoLoanMarketsFacet.Market memory market = _myMarket();
        // the cover gate: a live fee principal checkpoints first (zero principal has nothing to
        // accrue and no snapshot worth refreshing - a borrow re-baselines itself), then the
        // withdrawal is refused (retriably) unless the collateral it leaves covers the position
        // - debt and fee are paid in loan tokens through repay, never taken from the collateral
        if (feePrincipal != 0) {
            _checkpointFee(market);
        }
        _requirePositionCovered(market, amount);
        _markOperationUsed(operationId);

        IMorpho(market.morpho).withdrawCollateral(
            market.marketParams, amount, address(this), address(this)
        );
        // saturating: with no principal the record can be stale, and it stays at or below the
        // position, which is all the liquidation test needs
        feeBaseCollateral = feeBaseCollateral > amount ? feeBaseCollateral - SafeCast.toUint128(amount) : 0;
        emit CollateralWithdrawn(_parentAccount(), operationId, amount, _guid);

        // the return leg, in the same execution; the LayerZero fee rode in as compose value
        // and its excess goes to the parent
        _bridgeHome(_getTransport(), amount, minAmount, returnOptions, msg.value);
    }

    /// @dev The soft gates shared by the borrow and the withdraw - the deposit carries no id and no
    /// deadline (see {ComposeReceiverAccountBase._terminalSkipReason}):
    /// a duplicate id or a stale deadline completes the delivery without executing; the
    /// bridged FXRP stays for the fixed rails.
    function _skipped(
        bytes32 _operationId,
        uint64 _deadline,
        bytes32 _guid
    )
        private
        returns (bool)
    {
        uint8 reason = _terminalSkipReason(_operationId, _deadline);
        if (reason == 0) {
            return false;
        }
        emit LoanActionSkipped(_parentAccount(), _operationId, reason, _guid);
        return true;
    }

    /// @dev The withdraw action's return leg: sends `_amount` FXRP to this account's
    /// own Flare address (same address on every chain) with the redeem-home compose - the
    /// action and nothing else - and the Flare twin redeems whatever it then holds, this
    /// arrival included, at the price of its own public rail. `_amount` is gross and
    /// `_minAmount` the floor the sender signed on what must arrive; equal validated decimals
    /// mean the two differ only by the fee-capable adapter's cut, and a cut above the allowance
    /// reverts the delivery (retriable) rather than taking it from the user's collateral.
    /// `_options` carry the Flare-side gas and, as compose value, the redemption's executor
    /// fee - at least the Flare controller's configured fee, or the redeem-home parks until a
    /// delivery brings it or anyone sweeps (the operator, for a packet a fee change caught in
    /// flight). Exactly the quoted fee is spent from `_value` and the excess is forwarded to the
    /// parent (the endpoint is no refund target).
    function _bridgeHome(
        IComposeTransportFacet.Transport memory _transport,
        uint256 _amount,
        uint256 _minAmount,
        bytes memory _options,
        uint256 _value
    )
        private
    {
        // a peer mutation on the OFT after configuration must fail closed
        require(
            IOAppCore(_transport.oft).peers(_transport.originEid) == _transport.originPeer,
            WrongOriginPeer()
        );
        SendParam memory sendParam = SendParam({
            dstEid: _transport.originEid,
            to: bytes32(uint256(uint160(address(this)))),
            amountLD: _amount,
            minAmountLD: _minAmount,
            extraOptions: _options,
            composeMsg: abi.encode(PAYLOAD_VERSION_1, ACTION_REDEEM_HOME, bytes("")),
            oftCmd: ""
        });

        MessagingFee memory fee = IOFT(_transport.oft).quoteSend(sendParam, false);
        require(_value >= fee.nativeFee, InsufficientFundsForBridgeHome(fee.nativeFee));

        IERC20 fxrp = IERC20(IOFT(_transport.oft).token());
        fxrp.forceApprove(_transport.oft, _amount);
        // two false positives on this call: slither arbitrary-send-eth (recipient is the
        // governance-set OFT, value capped by the _value check above) and solhint
        // check-send-result (this is the OFT's `send`, not address.send; it reverts on failure)
        // slither-disable-start arbitrary-send-eth
        // solhint-disable-next-line check-send-result
        (MessagingReceipt memory receipt, ) = IOFT(_transport.oft).send{value: fee.nativeFee}(
            sendParam,
            fee,
            _parentAccount()
        );
        // slither-disable-end arbitrary-send-eth
        fxrp.forceApprove(_transport.oft, 0);

        emit FXrpBridgedToOrigin(_parentAccount(), _amount, _transport.originEid, receipt.guid);
        // the excess never strands here (no native rail)
        _sweepValueToParent(_value - fee.nativeFee);
    }

    /// @dev Forwards compose value to the parent - a skipped withdraw's whole value, or the
    /// return leg's excess over the quoted fee: the endpoint is not a valid refund target, and
    /// this account has no native exit.
    function _sweepValueToParent(
        uint256 _value
    )
        private
    {
        if (_value == 0) {
            return;
        }
        // slither-disable-start arbitrary-send-eth
        // solhint-disable-next-line avoid-low-level-calls
        (bool success, ) = _parentAccount().call{value: _value}("");
        // slither-disable-end arbitrary-send-eth
        require(success, RefundFailed());
        emit NativeSweptToParent(_parentAccount(), _value);
    }

    /// @dev Prices the elapsed period at the SNAPSHOTTED terms - `owed = max(floor·P·T,
    /// I + spread·P·T)` with `I = max(0, D − P)` over the debt `D` the principal reached
    /// ({_debtReached}), so a repayment outside the rails lowers the interest observed while a
    /// liquidation keeps the interest the position bore - then re-baselines: principal, its
    /// shares and the collateral to the position now, clock to now, snapshot to the current
    /// terms. The re-baseline runs on EVERY checkpoint (a first borrow must accrue at current
    /// terms, not stale ones). Shares-first: zero principal makes no Morpho call; a zero elapsed
    /// period skips the fee math but still re-reads the position raw (a same-block checkpoint
    /// after an external repayment must not keep a stale base); zero live shares read the stored
    /// totals without accruing, so the IRM is never touched.
    function _checkpointFee(
        IMorphoLoanMarketsFacet.Market memory _market
    )
        private
    {
        uint256 feeDeltaX18 = 0;
        uint256 principal = feePrincipal;
        if (principal != 0) {
            uint256 elapsed = block.timestamp - feeLastCheckpoint;
            if (elapsed == 0) {
                _recordFeeBase(_market);
            } else {
                if (_borrowSharesOf(_market) > 0) {
                    IMorpho(_market.morpho).accrueInterest(_market.marketParams);
                }
                (, uint128 collateral, uint256 liveDebt, uint256 totalAssets, uint256 totalShares) =
                    _storedPosition(_market);
                feeDeltaX18 = LoanMath.feeDeltaX18(
                    principal,
                    _debtReached(liveDebt, collateral, totalAssets, totalShares),
                    elapsed,
                    feeSnapshotFloor,
                    feeSnapshotSpread
                );
                flareDebtX18 += feeDeltaX18;
                _recordFeeBase(_market);
            }
        }
        IMorphoLoanMarketsFacet.FeeTerms memory terms =
            IMorphoLoanMarketsFacet(controllerAddress).getLoanFeeTerms(_accountType());
        feeLastCheckpoint = uint64(block.timestamp);
        feeSnapshotFloor = terms.feeFloor;
        feeSnapshotSpread = terms.feeSpread;
        emit LoanFeeCheckpointed(_parentAccount(), feePrincipal, feeDeltaX18);
    }

    /// @dev The cover gate, shared by the withdraw (on the remainder after `_collateralOut`) and
    /// the borrow (on the post-borrow position, `_collateralOut == 0`): the collateral left in
    /// the position, valued at the market oracle's price, must cover {LoanMath.requiredCover} of
    /// the live debt and the collectible fee - Morpho's liquidation line with a fixed headroom, so
    /// the gate implies Morpho's health check and a fresh loan is gated at `EXIT_HEADROOM / LLTV`
    /// of its debt. The debt read here is accrued: the caller's checkpoint, or the borrow just
    /// made, brought it forward. With nothing owed the gate reads no oracle (and forgives
    /// debt-free dust); a zero, dead or reverting oracle values the remainder at nothing, so
    /// the action is refused - a withdrawal is then settled through repay, oracle-free, and
    /// retried, while a borrow needs the oracle back (Morpho, whose check ran first inside the
    /// borrow, reads it too). Reverts `InsufficientRemainingCollateral` with the two numbers.
    function _requirePositionCovered(
        IMorphoLoanMarketsFacet.Market memory _market,
        uint256 _collateralOut
    )
        private
    {
        (, uint256 debt) = _debtOf(_market);
        uint256 requiredCover =
            LoanMath.requiredCover(debt, flareDebtX18 / WAD, _market.marketParams.lltv);
        if (requiredCover == 0) {
            _forgiveFeeDust();
            return;
        }
        uint256 remainingValue =
            _remainingValue(_collateralOf(_market), _collateralOut, _oraclePrice(_market));
        require(
            remainingValue >= requiredCover,
            InsufficientRemainingCollateral(requiredCover, remainingValue)
        );
    }

    /// @dev A sub-unit remainder on a debt-free position can never be transferred (ERC-20
    /// moves whole units) and never grows again - a raw-zero gate would park the exit
    /// forever over dust, so it is forgiven when a gate passes with nothing collectible.
    /// Reached only then, so the remainder is sub-unit by construction; a whole unit or more
    /// is a collectible fee and is never forgiven.
    function _forgiveFeeDust()
        private
    {
        // only on a debt-free position: a live principal still accrues. The caller has
        // established that nothing is collectible, so what is left is below one base unit
        if (feePrincipal == 0 && flareDebtX18 > 0) {
            emit LoanFeeRemainderForgiven(flareDebtX18);
            flareDebtX18 = 0;
        }
    }

    /// @dev Re-reads the canonical debt after a Morpho borrow or repayment - never the
    /// requested amount (shares and rounding matter). The clock stays: the action's
    /// checkpoint just set it.
    function _syncFeePrincipal(
        IMorphoLoanMarketsFacet.Market memory _market
    )
        private
    {
        _recordFeeBase(_market);
        emit LoanFeePrincipalSynced(_parentAccount(), feePrincipal);
    }

    /// @dev Records the fee base from the position as Morpho stores it: the principal, the
    /// borrow shares behind it and the collateral ({_debtReached} compares against both).
    function _recordFeeBase(
        IMorphoLoanMarketsFacet.Market memory _market
    )
        private
    {
        (uint128 shares, uint128 collateral, uint256 debt, , ) = _storedPosition(_market);
        feePrincipal = debt;
        feeBaseShares = shares;
        feeBaseCollateral = collateral;
    }

    /// @dev The tail of {repay}, over the balance a closed or debt-free position leaves: pay
    /// `min(collectible, balance)` to the fee recipient ({_payFee}, best-effort, never rolling
    /// back the repayment), then reserve as much of the still-outstanding fee as the remaining
    /// balance covers (a later repay retries that reservation without a new top-up; an
    /// uncovered shortfall needs new funds) and send only the unreserved balance to the
    /// parent, once debt-free.
    function _collectFeeAndPushSurplus(
        IMorphoLoanMarketsFacet.Market memory _market,
        IERC20 _loanToken
    )
        private
    {
        uint256 balance = _loanToken.balanceOf(address(this));
        if (balance == 0) {
            return;
        }

        uint256 collectible = flareDebtX18 / WAD;
        if (collectible > 0) {
            address recipient = _feeRecipient();
            balance -= _payFee(_loanToken, recipient, Math.min(collectible, balance));
            uint256 reserved = Math.min(flareDebtX18 / WAD, balance);
            if (reserved > 0) {
                balance -= reserved;
                emit LoanFeeReserved(recipient, reserved);
            }
        }

        // best-effort: a parent the token refuses (RLUSD can freeze addresses) must never
        // roll back the repayment - a failed push waits here for a later repay
        if (balance > 0 && _borrowSharesOf(_market) == 0) {
            if (_loanToken.trySafeTransfer(_parentAccount(), balance)) {
                emit LoanSurplusRecovered(_parentAccount(), balance);
            } else {
                emit LoanSurplusRetained(_parentAccount(), balance);
            }
        }
    }

    /// @dev Pays `_amount` (non-zero) of the collectible fee from this account's balance to
    /// the fee recipient, best-effort: nothing moves when the token refuses the recipient
    /// (RLUSD can freeze addresses), so a repayment never rolls back; the fee debt shrinks
    /// only by the successfully requested transfer (conventional ERC-20 semantics are a
    /// registration policy). Not held by the pause: the money goes to Flare's own recipient,
    /// where an overcharge would be refundable, and holding it only made the paused route
    /// debt-first. Returns the amount paid - zero when nothing moved.
    function _payFee(
        IERC20 _loanToken,
        address _recipient,
        uint256 _amount
    )
        private
        returns (uint256)
    {
        if (!_loanToken.trySafeTransfer(_recipient, _amount)) {
            return 0;
        }
        flareDebtX18 -= _amount * WAD;
        emit LoanFeeCollected(_recipient, _amount);
        return _amount;
    }

    /// @dev The type's governance-set fee recipient. Debt, or a collectible fee, implies it
    /// is configured: the terms are the borrow activation marker.
    function _feeRecipient()
        private view
        returns (address)
    {
        return IMorphoLoanMarketsFacet(controllerAddress).getLoanFeeTerms(_accountType()).feeRecipient;
    }

    /// @dev The account's one market, bound write-once to its type. If its Morpho stops
    /// answering, this account's debt-gated paths block - inherent to where the position
    /// lives; hence the operational policy of only canonical immutable Morpho Blue deployments
    /// of the pinned v1.0.0 implementation (any other needs the conformance verification repeated).
    function _myMarket()
        private view
        returns (IMorphoLoanMarketsFacet.Market memory _market)
    {
        _market = IMorphoLoanMarketsFacet(controllerAddress).getLoanMarket(_accountType());
        require(
            _market.morpho != address(0),
            IMorphoLoanMarketsFacet.MarketNotRegistered(_accountType())
        );
    }

    /// @dev The account's collateral on its market, a plain Morpho storage read.
    function _collateralOf(
        IMorphoLoanMarketsFacet.Market memory _market
    )
        private view
        returns (uint128 _collateral)
    {
        (, , _collateral) = IMorpho(_market.morpho).position(
            MorphoMath.marketId(_market.marketParams), address(this)
        );
    }

    /// @dev The account's live borrow shares on its market - the exact test for "is there
    /// any debt", read live from Morpho every time (nothing is cached).
    function _borrowSharesOf(
        IMorphoLoanMarketsFacet.Market memory _market
    )
        private view
        returns (uint128 _borrowShares)
    {
        (, _borrowShares, ) = IMorpho(_market.morpho).position(
            MorphoMath.marketId(_market.marketParams), address(this)
        );
    }

    /// @dev The pause rule shared by the two collateral deposits: defending an indebted position
    /// survives a pause, like repayment, while a debt-free deposit is new exposure and waits it
    /// out. Debt increases and withdrawals never route through here - they stop outright. The
    /// pause is read first, on every deposit: unpaused - the common case - that is one
    /// controller read and no position read, and a controller that cannot answer the pause
    /// question refuses every deposit, indebted or not, the same fail-closed posture as
    /// {_checkNotPaused}.
    function _checkDepositAllowed(
        IMorphoLoanMarketsFacet.Market memory _market
    )
        private view
    {
        if (IPauseFacet(controllerAddress).isPaused()) {
            require(_borrowSharesOf(_market) > 0, IPauseFacet.IsPaused());
        }
    }

    /// @dev The account's live borrow shares and the assets needed to close them, using
    /// Morpho's rounded-up share conversion with virtual offsets ({MorphoMath}, pinned to
    /// upstream `SharesMathLib`).
    function _debtOf(
        IMorphoLoanMarketsFacet.Market memory _market
    )
        private view
        returns (uint128 _borrowShares, uint256 _fullDebt)
    {
        bytes32 marketId = MorphoMath.marketId(_market.marketParams);
        (, _borrowShares, ) = IMorpho(_market.morpho).position(marketId, address(this));
        (, , uint128 totalBorrowAssets, uint128 totalBorrowShares, , ) =
            IMorpho(_market.morpho).market(marketId);
        _fullDebt = MorphoMath.toAssetsUp(_borrowShares, totalBorrowAssets, totalBorrowShares);
    }

    /// @dev The position and the market's borrow totals as Morpho stores them, without accruing.
    function _storedPosition(
        IMorphoLoanMarketsFacet.Market memory _market
    )
        private view
        returns (
            uint128 _shares,
            uint128 _collateral,
            uint256 _debt,
            uint256 _totalBorrowAssets,
            uint256 _totalBorrowShares
        )
    {
        bytes32 marketId = MorphoMath.marketId(_market.marketParams);
        (, _shares, _collateral) = IMorpho(_market.morpho).position(marketId, address(this));
        (, , uint128 totalBorrowAssets, uint128 totalBorrowShares, , ) =
            IMorpho(_market.morpho).market(marketId);
        _totalBorrowAssets = totalBorrowAssets;
        _totalBorrowShares = totalBorrowShares;
        _debt = MorphoMath.toAssetsUp(_shares, totalBorrowAssets, totalBorrowShares);
    }

    /// @dev The debt the recorded principal reached, which the fee reads its interest from: the
    /// live debt, unless the position holds less collateral than expected - which, with every
    /// deposit and withdrawal tracked, only a liquidation causes. A liquidation burns shares, and
    /// with them interest the position bore; the recorded shares' value at the given totals keeps
    /// it. A repayment outside the rails leaves collateral in place and stays a donation, unless a
    /// liquidation falls in the same period, before or after it: the recorded shares are then
    /// credited whole, the repaid ones included.
    function _debtReached(
        uint256 _liveDebt,
        uint256 _collateral,
        uint256 _totalBorrowAssets,
        uint256 _totalBorrowShares
    )
        private view
        returns (uint256)
    {
        if (_collateral >= feeBaseCollateral) {
            return _liveDebt;
        }
        return Math.max(
            _liveDebt,
            MorphoMath.toAssetsUp(feeBaseShares, _totalBorrowAssets, _totalBorrowShares)
        );
    }

    /// @dev The market oracle's price, zero when the oracle is dead, reverting or answers zero -
    /// the gate's own treatment, so a quote reads the collateral the way the gate will.
    function _oraclePrice(
        IMorphoLoanMarketsFacet.Market memory _market
    )
        private view
        returns (uint256)
    {
        try IOracle(_market.marketParams.oracle).price() returns (uint256 _price) {
            return _price;
        } catch {
            return 0;
        }
    }

    /// @dev The market brought forward to this block the way Morpho's own accrual will bring it -
    /// the rate model's view rate compounded over the time since the market's last update, added
    /// to the borrow and supply totals within their uint128 bounds (a market without a rate model
    /// earns nothing) - and this account's shares, collateral and the debt those shares represent
    /// on the accrued totals. Reverts where the rate model does: every debt-bearing action would.
    function _marketView(
        IMorphoLoanMarketsFacet.Market memory _market
    )
        private view
        returns (MarketView memory _view)
    {
        bytes32 marketId = MorphoMath.marketId(_market.marketParams);
        (, uint128 shares, uint128 collateral) = IMorpho(_market.morpho).position(marketId, address(this));
        IMorpho.Market memory market;
        (
            market.totalSupplyAssets,
            market.totalSupplyShares,
            market.totalBorrowAssets,
            market.totalBorrowShares,
            market.lastUpdate,
            market.fee
        ) = IMorpho(_market.morpho).market(marketId);
        uint256 totalBorrowAssets = market.totalBorrowAssets;
        uint256 totalSupplyAssets = market.totalSupplyAssets;
        uint256 elapsed = block.timestamp - market.lastUpdate;
        if (elapsed != 0 && _market.marketParams.irm != address(0)) {
            uint256 rate = IIrm(_market.marketParams.irm).borrowRateView(_market.marketParams, market);
            uint256 interest =
                MorphoMath.wMulDown(totalBorrowAssets, MorphoMath.wTaylorCompounded(rate, elapsed));
            // canonical accrual adds into uint128 totals and reverts past them: so does the
            // projection, rather than quoting a position the accrual could not reach
            totalBorrowAssets = SafeCast.toUint128(totalBorrowAssets + interest);
            totalSupplyAssets = SafeCast.toUint128(totalSupplyAssets + interest);
        }
        _view.shares = shares;
        _view.collateral = collateral;
        _view.totalBorrowAssets = totalBorrowAssets;
        _view.totalBorrowShares = market.totalBorrowShares;
        _view.liquidity = totalSupplyAssets > totalBorrowAssets ? totalSupplyAssets - totalBorrowAssets : 0;
        _view.debt = MorphoMath.toAssetsUp(shares, totalBorrowAssets, market.totalBorrowShares);
    }

    /// @dev The fee as a checkpoint in this block would leave it: the carry plus the running
    /// period priced at the snapshotted terms - exactly {_checkpointFee}'s arithmetic, over what
    /// it would read: `_view`'s accrued totals while the account owes, the stored ones otherwise.
    function _projectedFeeX18(
        IMorphoLoanMarketsFacet.Market memory _market,
        MarketView memory _view
    )
        private view
        returns (uint256)
    {
        uint256 principal = feePrincipal;
        uint256 elapsed = block.timestamp - feeLastCheckpoint;
        if (principal == 0 || elapsed == 0) {
            return flareDebtX18;
        }
        uint256 debtReached;
        if (_view.shares > 0) {
            debtReached =
                _debtReached(_view.debt, _view.collateral, _view.totalBorrowAssets, _view.totalBorrowShares);
        } else {
            (, uint128 collateral, uint256 liveDebt, uint256 totalAssets, uint256 totalShares) =
                _storedPosition(_market);
            debtReached = _debtReached(liveDebt, collateral, totalAssets, totalShares);
        }
        return flareDebtX18
            + LoanMath.feeDeltaX18(principal, debtReached, elapsed, feeSnapshotFloor, feeSnapshotSpread);
    }

    /// @dev The largest withdrawal the cover passes: the collateral above the amount that, at
    /// `_price`, is worth the cover (rounded up so the floor-valued remainder still covers). The
    /// whole collateral when nothing is owed; nothing under a dead oracle otherwise.
    function _maxWithdraw(
        MarketView memory _view,
        uint256 _collectible,
        uint256 _price,
        uint256 _lltv
    )
        private pure
        returns (uint256)
    {
        uint256 required = LoanMath.requiredCover(_view.debt, _collectible, _lltv);
        if (required == 0) {
            return _view.collateral;
        }
        if (_price == 0) {
            return 0;
        }
        uint256 keep = Math.mulDiv(required, ORACLE_PRICE_SCALE, _price, Math.Rounding.Ceil);
        return _view.collateral > keep ? _view.collateral - keep : 0;
    }

    /// @dev The lowest oracle price at which Morpho's health check still passes: its value floors
    /// twice (the collateral's value, then that value at the LLTV), so the price is the smallest
    /// that keeps the floored value at or above `ceil(debt / LLTV)`. Zero when debt-free; the
    /// maximum value with debt and no collateral.
    function _liquidationPrice(
        uint256 _debt,
        uint256 _collateral,
        uint256 _lltv
    )
        private pure
        returns (uint256)
    {
        if (_debt == 0) {
            return 0;
        }
        if (_collateral == 0) {
            return type(uint256).max;
        }
        uint256 minimumValue = Math.mulDiv(_debt, WAD, _lltv, Math.Rounding.Ceil);
        return Math.mulDiv(minimumValue, ORACLE_PRICE_SCALE, _collateral, Math.Rounding.Ceil);
    }

    /// @dev The largest further borrow the cover passes against `_value` of collateral. The
    /// closed form - the claim the value covers, less the debt and the fee's weight - ignores
    /// Morpho's share rounding on the way in and out, so the exact bound is found by bisection on
    /// the post-borrow debt as {_borrowTo} will see it: zero passes (the position is
    /// covered, or the closed form would be zero) and two past the closed form fails (one beyond
    /// what a share of rounding can add; were it ever to pass, the result would be a passing,
    /// non-maximal amount, never an unsafe one).
    function _maxBorrow(
        MarketView memory _view,
        uint256 _collectible,
        uint256 _value,
        uint256 _lltv
    )
        private pure
        returns (uint256)
    {
        uint256 allowedClaim = Math.mulDiv(_value, _lltv, LoanMath.EXIT_HEADROOM);
        uint256 owed = _view.debt + LoanMath.FEE_WEIGHT * _collectible;
        if (allowedClaim <= owed) {
            return 0;
        }
        uint256 low = 0;
        uint256 high = allowedClaim - owed + 2;
        while (high - low > 1) {
            uint256 mid = (low + high) / 2;
            if (LoanMath.requiredCover(_debtAfterBorrow(_view, mid), _collectible, _lltv) <= _value) {
                low = mid;
            } else {
                high = mid;
            }
        }
        return low;
    }

    /// @dev The debt after borrowing `_more` on the accrued market: Morpho rounds the new shares
    /// up on the way in and the debt up on the way out.
    function _debtAfterBorrow(
        MarketView memory _view,
        uint256 _more
    )
        private pure
        returns (uint256)
    {
        uint256 sharesUp = MorphoMath.toSharesUp(_more, _view.totalBorrowAssets, _view.totalBorrowShares);
        return MorphoMath.toAssetsUp(
            _view.shares + sharesUp, _view.totalBorrowAssets + _more, _view.totalBorrowShares + sharesUp
        );
    }

    /// @dev {repay}'s allocation of `_payment`, assuming every fee transfer succeeds: with live
    /// shares, the pro-rata fee share first when the payment is short of debt plus fee, then the
    /// debt (closed by shares when the rest covers it, otherwise repaid by assets with Morpho's
    /// rounding), then the tail - the collectible from what is left, a reservation for the rest,
    /// the surplus to the parent only once debt-free.
    function _simulateRepay(
        MarketView memory _view,
        uint256 _collectible,
        uint256 _payment
    )
        private pure
        returns (RepayPreview memory _preview)
    {
        uint256 balance = _payment;
        uint256 collectible = _collectible;
        uint256 debt = _view.debt;
        if (_view.shares != 0 && balance != 0) {
            if (balance < debt + collectible) {
                uint256 share = LoanMath.feeShare(balance, debt, collectible);
                _preview.feePaid = share;
                collectible -= share;
                balance -= share;
            }
            if (balance >= debt) {
                _preview.debtPaid = debt;
                debt = 0;
            } else {
                _preview.debtPaid = balance;
                uint256 repaidShares =
                    MorphoMath.toSharesDown(balance, _view.totalBorrowAssets, _view.totalBorrowShares);
                debt = MorphoMath.toAssetsUp(
                    _view.shares - repaidShares,
                    _view.totalBorrowAssets - balance,
                    _view.totalBorrowShares - repaidShares
                );
            }
            balance -= _preview.debtPaid;
        }
        if (balance != 0 && collectible != 0) {
            uint256 paid = Math.min(collectible, balance);
            _preview.feePaid += paid;
            collectible -= paid;
            balance -= paid;
            balance -= Math.min(collectible, balance);
        }
        if (balance != 0 && debt == 0) {
            _preview.surplus = balance;
        }
        _preview.debtAfter = debt;
        _preview.collectibleAfter = collectible;
    }

    /// @dev The smallest top-up whose {repay} (with `_idle` already on the account) leaves a
    /// position the cover passes at `_valueLeft`: a binary search over the top-up, since
    /// every unit paid shrinks both claims; closing both claims (debt plus collectible less the
    /// idle balance) always suffices, so the search is bounded.
    function _minimumTopUp(
        MarketView memory _view,
        uint256 _collectible,
        uint256 _idle,
        uint256 _valueLeft,
        uint256 _lltv
    )
        private pure
        returns (uint256)
    {
        uint256 owed = _view.debt + _collectible;
        uint256 high = owed > _idle ? owed - _idle : 0;
        uint256 low = 0;
        while (low < high) {
            uint256 mid = (low + high) / 2;
            if (_coveredAfterRepay(_view, _collectible, _idle + mid, _valueLeft, _lltv)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    /// @dev Whether the position {_simulateRepay} leaves after `_payment` is covered by
    /// `_valueLeft`.
    function _coveredAfterRepay(
        MarketView memory _view,
        uint256 _collectible,
        uint256 _payment,
        uint256 _valueLeft,
        uint256 _lltv
    )
        private pure
        returns (bool)
    {
        RepayPreview memory outcome = _simulateRepay(_view, _collectible, _payment);
        uint256 required = LoanMath.requiredCover(outcome.debtAfter, outcome.collectibleAfter, _lltv);
        return required == 0 || _valueLeft >= required;
    }

    /// @dev The value, in loan tokens, of the collateral left after `_collateralOut` at `_price`,
    /// rounded down; nothing when nothing is left.
    function _remainingValue(
        uint256 _collateral,
        uint256 _collateralOut,
        uint256 _price
    )
        private pure
        returns (uint256)
    {
        uint256 remaining = _collateral > _collateralOut ? _collateral - _collateralOut : 0;
        return Math.mulDiv(remaining, _price, ORACLE_PRICE_SCALE);
    }
}

contracts/smartAccounts/implementation/S.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import {ISubaccount} from "../../userInterfaces/ISubaccount.sol";
import {
    ISubaccountsFacet,
    SUBACCOUNT_TYPE_NONE
} from "../../userInterfaces/facets/ISubaccountsFacet.sol";
import {ControlledAccountBase} from "./ControlledAccountBase.sol";

/**
 * @title SubaccountBase
 * @notice The identity every subaccount implementation shares, on Flare and on the remote
 * chains and whatever the type does: the parent Personal Account and the type (both fixed at
 * deployment and part of the account's CREATE2 address), the frozen-proxy `initialize`, the
 * `onlyParent` gate and the type-aware beacon lookup. The frozen `SubaccountProxy` dictates this
 * surface ({ISubaccount}) for every type; implementing the interface directly is enough (the
 * generic test mock does), and this base is its one shared implementation.
 * @dev STORAGE: the parent and the type live in the `smartAccounts.SubaccountBase.State` namespace,
 * never in linear slots, so this base can grow without shifting a derived lineage; the derived
 * contract's own linear state starts right after {ControlledAccountBase}'s slot 0.
 */
abstract contract SubaccountBase is ISubaccount, ControlledAccountBase {

    /// @custom:storage-location erc7201:smartAccounts.SubaccountBase.State
    struct SubaccountState {
        address parentPersonalAccount;
        uint256 subaccountType;
    }

    bytes32 private constant SUBACCOUNT_STATE_POSITION =
        bytes32(erc7201("smartAccounts.SubaccountBase.State"));

    /// @dev The caller must be the parent Personal Account, fixed at deployment and part of
    /// this account's address.
    modifier onlyParent() {
        require(msg.sender == _getSubaccountState().parentPersonalAccount, OnlyParent());
        _;
    }

    /// @inheritdoc ISubaccount
    function initialize(
        address _controllerAddress,
        address _parentPersonalAccount,
        uint256 _subaccountType
    )
        external
    {
        _setController(_controllerAddress);
        require(_parentPersonalAccount != address(0), InvalidParentPersonalAccount());
        require(_subaccountType != SUBACCOUNT_TYPE_NONE, ISubaccountsFacet.InvalidSubaccountType());
        SubaccountState storage state = _getSubaccountState();
        state.parentPersonalAccount = _parentPersonalAccount;
        state.subaccountType = _subaccountType;
        emit SubaccountInitialized(_controllerAddress, _parentPersonalAccount, _subaccountType);
    }

    /// @inheritdoc ISubaccount
    function parentPersonalAccount()
        external view
        returns (address)
    {
        return _parentAccount();
    }

    /// @inheritdoc ISubaccount
    function subaccountType()
        external view
        returns (uint256)
    {
        return _accountType();
    }

    /// @inheritdoc ISubaccount
    function implementation()
        external view
        returns (address)
    {
        // controller is the beacon; it resolves the implementation for this subaccount type
        return ISubaccountsFacet(controllerAddress).implementationForType(_accountType());
    }

    function _parentAccount()
        internal view
        returns (address)
    {
        return _getSubaccountState().parentPersonalAccount;
    }

    function _accountType()
        internal view
        returns (uint256)
    {
        return _getSubaccountState().subaccountType;
    }

    function _getSubaccountState()
        private pure
        returns (SubaccountState storage _state)
    {
        bytes32 position = SUBACCOUNT_STATE_POSITION;
        // solhint-disable-next-line no-inline-assembly
        assembly {
            _state.slot := position
        }
    }
}

contracts/smartAccounts/interface/IIrm.s.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.4 <0.9;

import {IMorpho} from "./IMorpho.sol";

/**
 * @title IIrm
 * @notice Minimal Morpho Blue interest rate model interface: the two rate entry points, as in
 * the canonical `morpho-org/morpho-blue` `IIrm` v1.0.0. `borrowRateView` is what the account's
 * read surface uses to bring a market's debt forward to the current block the way Morpho's own
 * accrual will; `borrowRate` is the state-changing twin Morpho calls when it accrues. Kept as our
 * own MIT code because the upstream files are GPL-2.0-or-later; conformance is pinned by
 * `test/unit/smartAccounts/MorphoConformance.t.sol`.
 */
interface IIrm {
    /**
     * @notice Returns the borrow rate per second (WAD) of `marketParams`, updating the model's
     * state; called by Morpho on accrual.
     */
    function borrowRate(
        IMorpho.MarketParams memory marketParams,
        IMorpho.Market memory market
    )
        external
        returns (uint256);

    /**
     * @notice Returns the borrow rate per second (WAD) of `marketParams` without updating the
     * model's state.
     */
    function borrowRateView(
        IMorpho.MarketParams memory marketParams,
        IMorpho.Market memory market
    )
        external view
        returns (uint256);
}

contracts/smartAccounts/interface/IMorph.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.4 <0.9;

/**
 * @title IMorpho
 * @notice Minimal Morpho Blue interface: only the entry points the loan-chain-side
 * subaccount uses. Signatures and the `MarketParams` layout match the canonical
 * `morpho-org/morpho-blue` `IMorpho` v1.0.0. Kept as our own MIT code because the upstream
 * files are GPL-2.0-or-later; conformance is pinned by `test/unit/smartAccounts/MorphoConformance.t.sol`.
 */
interface IMorpho {

    struct MarketParams {
        address loanToken;
        address collateralToken;
        address oracle;
        address irm;
        uint256 lltv;
    }

    /// @dev The market's totals as canonical Morpho stores them - the six words `market(id)`
    /// returns, in that order, and the second argument of the interest rate model's rate
    /// functions.
    struct Market {
        uint128 totalSupplyAssets;
        uint128 totalSupplyShares;
        uint128 totalBorrowAssets;
        uint128 totalBorrowShares;
        uint128 lastUpdate;
        uint128 fee;
    }

    /**
     * @notice Supplies collateral on behalf of an account.
     * @param marketParams The market to supply collateral to.
     * @param assets The amount of collateral to supply.
     * @param onBehalf The account that owns the increased collateral position.
     * @param data Arbitrary callback data (unused by the caller in this repo).
     */
    function supplyCollateral(
        MarketParams memory marketParams,
        uint256 assets,
        address onBehalf,
        bytes memory data
    )
        external;

    /**
     * @notice Borrows assets against the caller's collateral position.
     * @param marketParams The market to borrow from.
     * @param assets The amount of assets to borrow (exactly one of assets/shares is non-zero).
     * @param shares The amount of shares to borrow.
     * @param onBehalf The account that owns the increased borrow position.
     * @param receiver The receiver of the borrowed assets.
     * @return assetsBorrowed The amount of assets borrowed.
     * @return sharesBorrowed The amount of shares borrowed.
     */
    function borrow(
        MarketParams memory marketParams,
        uint256 assets,
        uint256 shares,
        address onBehalf,
        address receiver
    )
        external
        returns (uint256 assetsBorrowed, uint256 sharesBorrowed);

    /**
     * @notice Accrues interest for a market, updating its totals.
     * @param marketParams The market to accrue interest for.
     */
    function accrueInterest(
        MarketParams memory marketParams
    )
        external;

    /**
     * @notice Withdraws collateral from the caller's position.
     * @param marketParams The market to withdraw collateral from.
     * @param assets The amount of collateral to withdraw.
     * @param onBehalf The account that owns the reduced collateral position.
     * @param receiver The receiver of the withdrawn collateral.
     */
    function withdrawCollateral(
        MarketParams memory marketParams,
        uint256 assets,
        address onBehalf,
        address receiver
    )
        external;

    /**
     * @notice Repays assets on behalf of a borrow position.
     * @param marketParams The market to repay to.
     * @param assets The amount of assets to repay (exactly one of assets/shares is non-zero).
     * @param shares The amount of shares to repay.
     * @param onBehalf The account whose debt is reduced.
     * @param data Arbitrary callback data (unused by the caller in this repo).
     * @return assetsRepaid The amount of assets repaid.
     * @return sharesRepaid The amount of shares repaid.
     */
    function repay(
        MarketParams memory marketParams,
        uint256 assets,
        uint256 shares,
        address onBehalf,
        bytes memory data
    )
        external
        returns (uint256 assetsRepaid, uint256 sharesRepaid);
    /**
     * @notice Returns an account's position in a market.
     * @param id The market id (`keccak256(abi.encode(marketParams))`).
     * @param user The account.
     * @return supplyShares The account's supply shares.
     * @return borrowShares The account's borrow shares.
     * @return collateral The account's collateral.
     */
    function position(
        bytes32 id,
        address user
    )
        external view
        returns (uint256 supplyShares, uint128 borrowShares, uint128 collateral);

    /**
     * @notice Returns a market's state.
     * @param id The market id.
     * @return totalSupplyAssets The market's total supplied assets.
     * @return totalSupplyShares The market's total supply shares.
     * @return totalBorrowAssets The market's total borrowed assets.
     * @return totalBorrowShares The market's total borrow shares.
     * @return lastUpdate The last accrual timestamp; zero means the market was never created.
     * @return fee The market's fee.
     */
    function market(
        bytes32 id
    )
        external view
        returns (
            uint128 totalSupplyAssets,
            uint128 totalSupplyShares,
            uint128 totalBorrowAssets,
            uint128 totalBorrowShares,
            uint128 lastUpdate,
            uint128 fee
        );
}

contracts/smartAccounts/interface/IOracl.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.4 <0.9;

/**
 * @title IOracle
 * @notice Minimal interface of a Morpho Blue market oracle: the price of one collateral-token
 * asset quoted in loan-token assets, scaled by 1e36 (token decimals are baked into the scale,
 * so `loanAmount = mulDiv(collateralAmount, price, 1e36)` - no second decimals adjustment).
 * The interface carries no freshness or timestamp field; trusting it is part of trusting the
 * write-once market it belongs to, exactly as the market's own liquidations already do.
 */
interface IOracle {
    /**
     * @notice Returns the price of one collateral asset in loan-token assets, 1e36-scaled.
     */
    function price() external view returns (uint256);
}

contracts/smartAccounts/library/LoanMath.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

/**
 * @title LoanMath
 * @notice The Flare fee's and the cover gate's arithmetic, in one place: the loan-chain
 * subaccount's actions compute with these functions and its read surface quotes with the same
 * ones, so a quote and the refusal it predicts cannot drift apart. Pure - every input is a plain
 * number the caller has already read.
 */
library LoanMath {
    /// @dev WAD fixed point: the fee rates' and the headroom's precision.
    uint256 internal constant WAD = 1e18;
    /// @dev The fee's year: annual WAD rates accrue over a fixed 365-day year.
    uint256 internal constant YEAR = 365 days;
    /// @dev The cover gate's headroom over Morpho's liquidation line (WAD): the collateral left
    /// after an action must be worth `EXIT_HEADROOM / LLTV` of the covered claim, where Morpho
    /// itself lets a position run down to `1 / LLTV` (its withdraw, borrow and liquidation tests
    /// are one and the same). At the launch market's 77% LLTV this is exactly 1.5x.
    uint256 internal constant EXIT_HEADROOM = 1.155e18;
    /// @dev The fee's weight in the covered claim, `debt + FEE_WEIGHT * collectible`: the junior
    /// claim behind the debt counts twice, so a debt-free exit needs 3x the collectible.
    /// Deliberately not liquidation-proof (the accepted junior-claim risk).
    uint256 internal constant FEE_WEIGHT = 2;

    /// @dev The cover gate's required cover, in loan tokens: `(debt + FEE_WEIGHT * collectible)
    /// * EXIT_HEADROOM / lltv`, rounded up; zero when nothing is owed.
    function requiredCover(
        uint256 _debt,
        uint256 _collectible,
        uint256 _lltv
    )
        internal pure
        returns (uint256)
    {
        uint256 claim = _debt + FEE_WEIGHT * _collectible;
        if (claim == 0) {
            return 0;
        }
        return Math.mulDiv(claim, EXIT_HEADROOM, _lltv, Math.Rounding.Ceil);
    }

    /// @dev The fee one elapsed period adds, at WAD precision (base units x 1e18):
    /// `max(P * floor * T / YEAR, I * WAD + P * spread * T / YEAR) - I * WAD` over the principal
    /// `P` at the period's start (base units), the WAD annual rates, the period's length `T` in
    /// seconds of the 365-day year, and the market interest `I = max(0, debtReached - P)` the
    /// period produced in base units, from the debt the principal reached - a debt that fell
    /// counts as zero interest, so the delta never underflows. Each rate term is one `mulDiv`
    /// rounded down, the interest exact. Zero for a zero principal or a zero period.
    function feeDeltaX18(
        uint256 _principal,
        uint256 _debtReached,
        uint256 _elapsed,
        uint256 _floor,
        uint256 _spread
    )
        internal pure
        returns (uint256)
    {
        if (_principal == 0 || _elapsed == 0) {
            return 0;
        }
        uint256 interestX18 = (_debtReached > _principal ? _debtReached - _principal : 0) * WAD;
        uint256 owedX18 = Math.max(
            Math.mulDiv(_principal * _floor, _elapsed, YEAR),
            interestX18 + Math.mulDiv(_principal * _spread, _elapsed, YEAR)
        );
        return owedX18 - interestX18;
    }

    /// @dev The fee's share of a payment short of debt plus fee, `payment * collectible / (debt +
    /// collectible)` rounded down; the remainder goes to the debt.
    function feeShare(
        uint256 _payment,
        uint256 _debt,
        uint256 _collectible
    )
        internal pure
        returns (uint256)
    {
        return Math.mulDiv(_payment, _collectible, _debt + _collectible);
    }
}

contracts/smartAccounts/library/MorphoMa.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IMorpho} from "../interface/IMorpho.sol";

/**
 * @title MorphoMath
 * @notice Our own MIT implementation of the pieces of Morpho Blue arithmetic the accounts
 * depend on: the market id (`keccak256(abi.encode(marketParams))`, Morpho's `MarketParamsLib.id`),
 * the share/asset conversions with Morpho's virtual offsets (`SharesMathLib`: one virtual
 * asset, 1e6 virtual shares, rounding as named) and the interest compounding of its accrual
 * (`MathLib.wTaylorCompounded`, the third-order Taylor polynomial of `e^(rate * elapsed) - 1`
 * that `_accrueInterest` applies to the borrow total). Written here rather than imported because the
 * upstream libraries are GPL-2.0-or-later; equality with `morpho-blue` v1.0.0 (commit 55d2d99)
 * is pinned by `test/unit/smartAccounts/MorphoConformance.t.sol` on fixed vectors. The full-precision `mulDiv`
 * agrees with Morpho's checked multiplication everywhere Morpho itself does not revert.
 */
library MorphoMath {
    uint256 internal constant VIRTUAL_SHARES = 1e6;
    uint256 internal constant VIRTUAL_ASSETS = 1;
    uint256 internal constant WAD = 1e18;

    /// @dev Morpho's market id for `_marketParams`.
    function marketId(IMorpho.MarketParams memory _marketParams) internal pure returns (bytes32) {
        return keccak256(abi.encode(_marketParams));
    }

    /// @dev Shares for `_assets`, rounded up.
    function toSharesUp(
        uint256 _assets,
        uint256 _totalAssets,
        uint256 _totalShares
    )
        internal pure
        returns (uint256)
    {
        return Math.mulDiv(
            _assets, _totalShares + VIRTUAL_SHARES, _totalAssets + VIRTUAL_ASSETS, Math.Rounding.Ceil
        );
    }

    /// @dev Shares for `_assets`, rounded down.
    function toSharesDown(
        uint256 _assets,
        uint256 _totalAssets,
        uint256 _totalShares
    )
        internal pure
        returns (uint256)
    {
        return Math.mulDiv(_assets, _totalShares + VIRTUAL_SHARES, _totalAssets + VIRTUAL_ASSETS);
    }

    /// @dev Assets for `_shares`, rounded up - what closing a borrow position costs.
    function toAssetsUp(
        uint256 _shares,
        uint256 _totalAssets,
        uint256 _totalShares
    )
        internal pure
        returns (uint256)
    {
        return Math.mulDiv(
            _shares, _totalAssets + VIRTUAL_ASSETS, _totalShares + VIRTUAL_SHARES, Math.Rounding.Ceil
        );
    }

    /// @dev `_x * _y / 1e18`, rounded down (Morpho's `wMulDown`).
    function wMulDown(
        uint256 _x,
        uint256 _y
    )
        internal pure
        returns (uint256)
    {
        return Math.mulDiv(_x, _y, WAD);
    }

    /// @dev Morpho's `wTaylorCompounded`: the sum of the first three terms of the Taylor
    /// expansion of `e^(_x * _n) - 1`, each rounded down, for a per-second WAD rate `_x` over
    /// `_n` seconds - the factor `_accrueInterest` multiplies the borrow total by.
    function wTaylorCompounded(
        uint256 _x,
        uint256 _n
    )
        internal pure
        returns (uint256)
    {
        uint256 firstTerm = _x * _n;
        uint256 secondTerm = Math.mulDiv(firstTerm, firstTerm, 2 * WAD);
        uint256 thirdTerm = Math.mulDiv(secondTerm, firstTerm, 3 * WAD);
        return firstTerm + secondTerm + thirdTerm;
    }
}

contracts/userInterfaces/IBridgingSubacc.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.4 <0.9;

import {IComposeReceiverAccountBase} from "./IComposeReceiverAccountBase.sol";
import {ISubaccount} from "./ISubaccount.sol";

/**
 * @title IBridgingSubaccount
 * @notice The surface every Flare subaccount type that bridges FXRP to its own address on a
 * remote chain shares, whatever the type does there: the compose ingress of its own remote
 * twin's messages (see {IComposeReceiverAccountBase}), authenticated against the transport
 * derived from the type's bridge route, and the errors of the forward move every one of its
 * instructions is sent through. The instructions themselves, and what an arriving message
 * does, are declared on the type's interface (e.g. {ILoanSubaccount}); whether the type also
 * redeems its idle FXRP is a separate surface ({IRedeemingSubaccount}).
 */
interface IBridgingSubaccount is IComposeReceiverAccountBase, ISubaccount {

    /**
     * @notice Reverts if this subaccount's type has no complete bridge route on the controller:
     * no FXRP OFT adapter, a type never pinned to a remote chain, a suspended type, or a
     * cleared route.
     */
    error BridgeRouteNotConfigured();

    /**
     * @notice Reverts if the OFT's live peer for the destination chain no longer matches the
     * peer pinned in the controller's bridge route for this subaccount's type.
     */
    error WrongDestinationPeer();

    /**
     * @notice Reverts if the value sent with a forward move does not cover the LayerZero
     * messaging fee of the bridge.
     * @param messagingFee The required messaging fee.
     */
    error InsufficientFundsForBridge(
        uint256 messagingFee
    );

    /**
     * @notice Reverts if the caller's excess native refund could not be returned.
     */
    error RefundFailed();

    /**
     * @notice Reverts if a forward move's signed arrival floor is not one this send can honor:
     * above the amount it carries, or zero on a send that carries tokens.
     * @param amount The amount being sent.
     * @param minAmount The floor named by the instruction.
     */
    error InvalidMinAmount(
        uint256 amount,
        uint256 minAmount
    );

    /**
     * @notice Reverts if the requested bridge amount exceeds the account's FXRP balance.
     * @param amount The requested amount.
     * @param balance The account's FXRP balance.
     */
    error AmountExceedsBalance(
        uint256 amount,
        uint256 balance
    );
}

contracts/userInterfaces/IComposeReceive.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.4 <0.9;

import {ILayerZeroComposer} from "@layerzerolabs/lz-evm-protocol-v2/contracts/interfaces/ILayerZeroComposer.sol";
import {IControlledAccount} from "./IControlledAccount.sol";

/// @dev Compose payload schema version 1, shared by every compose receiver on either
/// chain. The payload is `abi.encode(uint8 version, uint8 action, bytes actionData)`; the
/// action space is defined per receiving contract.
uint8 constant PAYLOAD_VERSION_1 = 1;

/// @dev Skip reason: the operation id was already consumed (a retried instruction delivered
/// twice must not turn one intended action into two).
uint8 constant SKIP_REASON_DUPLICATE = 1;

/// @dev Skip reason: the deadline passed before delivery; the user's intent is stale. The
/// operation id is not consumed, so the same intent can be retried with a fresh deadline.
uint8 constant SKIP_REASON_EXPIRED = 2;

/**
 * @title IComposeReceiverAccountBase
 * @notice The shared authenticated `lzCompose` surface of the same-address cross-chain
 * accounts: the loan-chain subaccount and Personal Account (Ethereum, at launch), and the Flare
 * loan subaccount as the receiver of its own bridge-back. It authenticates the endpoint, the
 * OFT, the origin chain, the pinned peer and `composeFrom`, and tracks replay state for the
 * signed actions (an id-less action, such as the Flare redeem-home - which itself originates
 * from a signed withdraw - carries no id and relies on the endpoint's at-most-once
 * compose delivery). Users are XRPL-only and their
 * signatures become on-chain authority only on Flare, so every action arriving here was sent by
 * this same address on the other chain — the account's own twin. Account-specific
 * parent-driven and public rails live outside this interface.
 */
interface IComposeReceiverAccountBase is ILayerZeroComposer, IControlledAccount {

    /**
     * @notice Reverts if `lzCompose` is called by anything other than the LayerZero endpoint.
     */
    error OnlyEndpoint();

    /**
     * @notice Reverts if native value is attached to `lzCompose` for an action that does not
     * spend it within the same call. Rejecting it keeps a mistaken delivery retriable without
     * value; an action that spends or forwards the value in the same call opts in (the Flare
     * redeem-on-arrival, the loan-chain atomic withdraw).
     */
    error NonZeroComposeValue();

    /**
     * @notice Reverts if the compose sender (`_from`) is not the configured FXRP OFT.
     * @param from The compose sender.
     */
    error WrongComposeSender(
        address from
    );

    /**
     * @notice Reverts if the composed message did not originate on the configured origin chain.
     * @param srcEid The source endpoint id of the message.
     */
    error WrongSourceEid(
        uint32 srcEid
    );

    /**
     * @notice Reverts if the source-chain sender of the composed message is not this account
     * itself (its own address on the origin chain).
     * @param composeFrom The source-chain sender.
     */
    error WrongComposeFrom(
        bytes32 composeFrom
    );

    /**
     * @notice Reverts if the delivered GUID does not equal the one recomputed from the pinned
     * origin peer: the compose wrapper alone does not commit to the source OApp, so this
     * check is what binds the message to the pinned peer.
     * @param guid The delivered GUID.
     */
    error WrongGuid(
        bytes32 guid
    );

    /**
     * @notice Reverts on a payload with an unsupported schema version.
     * @param version The unsupported version.
     */
    error UnsupportedPayloadVersion(
        uint8 version
    );

    /**
     * @notice Reverts on a payload with an unsupported action.
     * @param action The unsupported action.
     */
    error UnsupportedAction(
        uint8 action
    );

    /**
     * @notice Reverts on a payload whose operation id is zero.
     */
    error InvalidOperationId();

    /**
     * @notice Returns whether an operation id has been consumed. An id is consumed on
     * execution; an expired skip leaves it unconsumed (the intent can retry under it), and a
     * duplicate skip means it was already consumed. Derived accounts may consume ids for
     * their own terminal reasons (see each account's skip reasons).
     * @param _operationId The operation id.
     * @return Whether the operation id is consumed.
     */
    function usedOperations(
        bytes32 _operationId
    )
        external view
        returns (bool);
}

contracts/userInterfaces/IControlledAcco.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.4 <0.9;

/**
 * @title IControlledAccount
 * @notice The one thing every account in the system has - Personal Accounts and subaccounts, on
 * Flare and on the remote chains: a controller (the MasterAccountController diamond), set once
 * at initialization. Every account interface extends this one, so `controllerAddress()` has a
 * single declaration and a single implementation (`ControlledAccountBase`).
 */
interface IControlledAccount {

    /**
     * @notice Reverts if the account is already initialized (including the implementation
     * contract itself, which is locked in its constructor).
     */
    error AlreadyInitialized();

    /**
     * @notice Reverts if the controller address is invalid (zero).
     */
    error InvalidControllerAddress();

    /**
     * @notice Returns the controller (MasterAccountController) address of this account.
     * @return The controller address.
     */
    function controllerAddress()
        external view
        returns (address);
}

contracts/userInterfaces/ILoanSubaccount.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.4 <0.9;

import {IBridgingSubaccount} from "./IBridgingSubaccount.sol";
import {IRedeemingSubaccount} from "./IRedeemingSubaccount.sol";

/*
 * The wire schema of a loan subaccount pair: the actions a compose payload can carry and the
 * destination kinds a borrow can disburse to. Both halves of a pair speak it - the Flare half
 * encodes it, the loan-chain half executes it - so it belongs to neither venue. What an action
 * then does to a position is the executing half's own; for the Morpho pair that is written out
 * in {IMorphoLoanSubaccountRemote}.
 */

/// @dev Borrow action: `actionData` is `abi.encode(bytes32 operationId, uint64 deadline,
/// uint8 destinationKind, bytes32 destination, uint256 borrowAmount, uint256 minComposeValue)`.
/// The floor is reserved for a destination kind that pays for its own onward delivery;
/// `DESTINATION_KIND_EVM` must leave it zero ({UnexpectedDeliveryValueFloor}). The market is not a
/// payload field: the account type fixes it (write-once), so the subaccount address itself
/// commits to the pool. The bridged collateral and any residue on the account are supplied, and
/// `borrowAmount` (non-zero) is borrowed and sent to `destination`; a zero bridged amount with
/// nothing idle borrows against the existing position. The operation id
/// must be non-zero and globally unique per subaccount across the actions that carry one (the
/// borrow and the withdraw); clients
/// retrying an expired intent must reuse its id only for the same intent with a fresh
/// deadline (a convention, not contract-enforced). A pure collateral deposit is its own action
/// (`ACTION_DEPOSIT_COLLATERAL`).
uint8 constant ACTION_BORROW = 1;

/// @dev Withdraw action: `actionData` is `abi.encode(bytes32 operationId, uint64 deadline,
/// uint256 withdrawAmount, uint256 minAmount, uint256 minComposeValue,
/// bytes returnOptions)`. The atomic
/// withdrawal: withdraws collateral from the account's one position and bridges it back to the
/// account's own Flare address in the same execution, with the redeem-home compose - no idle
/// window, so the redeposit ordering race cannot touch a withdrawal. `minAmount` is the
/// signed floor on what must arrive home (non-zero, at most `withdrawAmount`): the FXRP OFT
/// adapters are fee-capable and this leg is quoted only on delivery - after the instruction was
/// signed - so the allowance travels in the payload rather than being read there, and a cut
/// above it reverts the delivery (`SlippageExceeded`, retriable) instead of coming out of the
/// user's collateral. The loan chain re-validates it (`InvalidMinAmountReceived`) before any
/// branch that finalizes the packet. `minComposeValue` is the
/// delivery floor:
/// compose delivery is permissionless and LayerZero does not authenticate the delivered value,
/// so a delivery carrying less - execution and terminal skip alike - reverts
/// (`InsufficientDeliveryValue`), which is what stops a zero-value front-run from consuming
/// the packet and burning the prepaid value. `returnOptions` are the signed return-send
/// options (Flare-side gas and, as compose value, the redemption's executor fee - at least
/// the Flare controller's configured fee, which the redeem-home charges exactly as the public
/// sweep does; a delivery bringing less parks, retriable, until one brings it or anyone
/// sweeps); the return
/// fee is paid from the compose value delivered with this action - the only action that
/// accepts value - and the excess goes to the parent. Every failure reverts and leaves the
/// delivery retriable; what recovers it differs by cause, and for the Morpho pair
/// {IMorphoLoanSubaccountRemote} writes each cause out.
uint8 constant ACTION_WITHDRAW = 2;

/// @dev Deposit-collateral action: carries no action data (empty bytes) - no operation id, since
/// a re-issued deposit (a new packet; a delivered compose cannot replay) only adds the user's own
/// collateral, which the permissionless rail can do
/// with the same tokens anyway, and no deadline, since a late deposit is harmless. It supplies
/// the account's idle collateral and moves no debt.
uint8 constant ACTION_DEPOSIT_COLLATERAL = 3;

/// @dev Redeem-home action, the one the Flare half receives: the compose the loan-chain twin's
/// bridge-back attaches to the FXRP it returns - the withdraw action's return leg.
/// Its `actionData` is empty: the packet is an instruction to redeem, not a number, and the
/// Flare account redeems whatever it holds on arrival - the packet's credit and any idle
/// balance beside it - exactly as {IRedeemingSubaccount.sweepRedeem} would, and at the same
/// price: the compose value is the executor fee and must reach the controller's configured one
/// ({IRedeemingSubaccount.InsufficientFundsForRedeem}), so a delivery bringing less reverts and
/// stays retriable, for a `lzCompose` retry carrying the current fee or for anyone's sweep -
/// which is what the operator can for a packet a fee change caught in flight. No deadline: a
/// late packet finds the balance a sweep would find and does with it only what anyone may do.
uint8 constant ACTION_REDEEM_HOME = 4;

/// @dev Cancel action: `actionData` is `abi.encode(bytes32 operationId)`. Message-only, and the
/// one action that withdraws an authority instead of using one: it consumes the id so the packet
/// that carried it can never execute, and does nothing else. It carries no deadline of its own (a
/// late cancellation is either
/// unnecessary or still correct). Sending one is NOT cancellation: the two packets race, and an
/// original that arrives first executes normally, after which the cancellation finds the id
/// consumed and finalizes quietly without an event - so a client resolves a sent cancellation
/// by whichever arrives, {LoanActionCancelled} or the original action's own execution event,
/// and either ends the instruction's live state. Cancelling an id that was never issued is
/// allowed and simply burns it, which is what makes the action idempotent and its delivery
/// terminal on the first attempt.
uint8 constant ACTION_CANCEL = 5;

/// @dev The destination is an EVM address (cleanly zero-padded into the `bytes32`), paid by a
/// plain ERC-20 transfer — typically an exchange deposit address, or the user's own
/// loan-chain Personal Account (the parent, a functional compose-driven account). It may not
/// be zero or the subaccount itself (the proceeds could only repay the new debt).
uint8 constant DESTINATION_KIND_EVM = 1;

/// @dev Reserved: an XRPL address reached over Wormhole. Not implemented yet (Wormhole specs
/// pending); payloads using it revert.
uint8 constant DESTINATION_KIND_XRPL_WORMHOLE = 2;

/**
 * @title ILoanSubaccount
 * @notice User interface for deterministic loan subaccounts on Flare: the parent-driven loan
 * instructions, typed payload encoders over the shared forward move. The permissionless rail
 * (`sweepRedeem`) is the redeeming surface every type whose idle FXRP means home shares, declared
 * on {IRedeemingSubaccount}; the compose ingress of the loan-chain twin's messages is the bridging
 * surface, declared on {IBridgingSubaccount}; the redeem-home action those messages carry
 * ({ACTION_REDEEM_HOME}) is this type's own, dispatched into the same redemption as the rail.
 */
interface ILoanSubaccount is IBridgingSubaccount, IRedeemingSubaccount {

    /// @notice The signed LayerZero options and delivery-value floor of the two-leg withdrawal.
    /// The operator quotes the return leg first, against `returnOptions` - so that quote already
    /// contains the redemption's executor fee those options buy - puts it (plus headroom; the
    /// excess lands on the parent) into `destinationOptions` as compose value, then quotes and
    /// sends the first message. One payment, made on Flare, covers both legs and the
    /// redemption.
    struct WithdrawOptions {
        /// @notice Flare -> loan chain: the withdraw compose's gas and, as compose value, the
        /// native that pays for the whole way back - the return leg's LayerZero fee, which
        /// itself buys the native the Flare compose arrives with, the redemption's executor
        /// fee. Nothing is paid on the loan chain out of the user's own funds.
        bytes destinationOptions;
        /// @notice Loan chain -> Flare: the redeem-home compose's gas and, as compose value,
        /// the redemption's executor fee - at least the Flare controller's configured fee, the
        /// price the public sweep pays too; a delivery bringing less parks the redemption
        /// (retriable) until a `lzCompose` retry brings the current fee or anyone sweeps - the
        /// operator can do either, when a fee change caught a packet in
        /// flight. The fee is read when the packet arrives, and a change to it is timelocked -
        /// known in advance, so a return leg signed before one can be sized for it. Signed
        /// end-to-end
        /// and frozen into the instruction - a bad blob parks the withdrawal until a fresh
        /// instruction (reuse the same operation id, so the parked packet terminal-skips as a
        /// duplicate).
        bytes returnOptions;
        /// @notice The delivery-value floor (non-zero): compose delivery is permissionless and
        /// LayerZero does not authenticate the delivered value, so the loan chain refuses any
        /// delivery of this withdraw - execution and terminal skip alike - carrying less than
        /// this. Set it to the compose value bought in `destinationOptions`, so a front-run
        /// with less cannot consume the packet and burn the prepaid value - and never above
        /// it: the floor is checked before the expiry skip, so a packet whose bought value is
        /// below its own floor reverts on every delivery, even after its deadline, and never
        /// finalizes (no funds at risk - the value was never delivered, and a reissue on the
        /// same operation id executes normally - but the orphan stays queued at the endpoint).
        uint256 minComposeValue;
    }

    /**
     * @notice Emitted when a borrow instruction is sent to this account's loan-chain twin.
     * @param parentPersonalAccount The parent Personal Account address.
     * @param operationId The user-chosen operation id.
     * @param collateralAmount FXRP bridged with the instruction, to become collateral.
     * @param borrowAmount Loan-token amount to borrow and disburse (non-zero).
     * @param destinationKind The disbursement destination kind.
     * @param destination The disbursement destination.
     * @param destinationEid The loan chain's LayerZero endpoint id.
     * @param guid The LayerZero message id.
     */
    event BorrowInstructionSent(
        address indexed parentPersonalAccount,
        bytes32 operationId,
        uint256 collateralAmount,
        uint256 borrowAmount,
        uint8 destinationKind,
        bytes32 destination,
        uint32 destinationEid,
        bytes32 guid
    );

    /**
     * @notice Emitted when a deposit-collateral instruction is sent to this account's
     * loan-chain twin.
     * @param parentPersonalAccount The parent Personal Account address.
     * @param amount FXRP bridged with the instruction, to become collateral.
     * @param destinationEid The loan chain's LayerZero endpoint id.
     * @param guid The LayerZero message id.
     */
    event CollateralDepositInstructionSent(
        address indexed parentPersonalAccount,
        uint256 amount,
        uint32 destinationEid,
        bytes32 guid
    );

    /**
     * @notice Emitted when a cancellation is sent to this account's loan-chain twin. Sending it
     * is not cancellation: the two packets race, and the loan chain's {LoanActionCancelled} is
     * what says the id was actually consumed.
     * @param parentPersonalAccount The parent Personal Account address.
     * @param operationId The operation id the cancellation names.
     * @param destinationEid The LayerZero endpoint id of the loan chain.
     * @param guid The LayerZero message id of the cancellation.
     */
    event LoanCancelInstructionSent(
        address indexed parentPersonalAccount,
        bytes32 operationId,
        uint32 destinationEid,
        bytes32 guid
    );

    /**
     * @notice Emitted when a withdraw instruction is sent to this account's loan-chain twin.
     * @param parentPersonalAccount The parent Personal Account address.
     * @param operationId The user-chosen operation id.
     * @param amount Collateral to withdraw on the loan chain.
     * @param destinationEid The loan chain's LayerZero endpoint id.
     * @param guid The LayerZero message id.
     */
    event WithdrawInstructionSent(
        address indexed parentPersonalAccount,
        bytes32 operationId,
        uint256 amount,
        uint32 destinationEid,
        bytes32 guid
    );

    /**
     * @notice Reverts on a loan instruction whose arguments cannot execute on the loan chain:
     * a zero operation id or a deadline already passed (borrow and withdraw), a zero borrow,
     * deposit or withdrawal amount, a borrow disbursement that is not a clean non-zero EVM address other than
     * this account, a borrow naming a delivery-value floor for a destination kind that cannot
     * spend value, or a withdraw with a zero delivery-value floor. Checked here, before any
     * bridge fee is paid.
     */
    error InvalidLoanInstruction();

    /**
     * @notice The borrow instruction: bridges `_collateralAmount` FXRP (zero for a borrow
     * against existing collateral) with the typed payload that supplies it as collateral,
     * borrows `_borrowAmount` on the loan-chain twin's market and disburses it. A pure
     * collateral deposit is its own instruction, {depositCollateral}.
     * @dev Restricted to the parent Personal Account: the instruction names a loan action and
     * a user-chosen disbursement destination, so it must carry the user's XRPL signature. The
     * payload is built here, not passed in, so a malformed payload cannot reach the bridge; the
     * envelope and the EVM destination are validated before quoting
     * ({InvalidLoanInstruction}) and the loan chain re-validates on delivery. It sends to this
     * account's own cross-chain address through the configured pinned peer, sharing the
     * bridging core's guards: paused reverts, a configured route that is not suspended required,
     * live peer re-checked. `_extraOptions` must be type-3 options carrying both the destination
     * `lzReceive` gas and the `lzCompose` gas. `msg.value` must cover the LayerZero fee; the
     * excess is refunded to the parent. On the loan chain the borrow is also refused, retriably,
     * when the post-borrow position would fall under the cover gate
     * (`InsufficientRemainingCollateral`) - the same rule that gates {withdraw}: the collateral
     * must be worth `1.155 / LLTV` of the debt plus twice the collectible Flare fee.
     * @param _minCollateralAmount The least FXRP that must arrive on the loan chain; zero
     * when `_collateralAmount` is zero, otherwise non-zero and at most that amount. The
     * adapter is fee-capable, so this is the user's signed allowance for its cut - set it to
     * `_collateralAmount` when no fee is expected.
     * @param _collateralAmount FXRP to bridge and supply as collateral; may be zero, at most
     * the account's balance.
     * @param _borrowAmount Loan-token amount to borrow and disburse; non-zero.
     * @param _destinationKind The disbursement destination kind (`DESTINATION_KIND_*`).
     * @param _destination The disbursement destination (a clean zero-padded EVM address for
     * `DESTINATION_KIND_EVM`).
     * @param _minComposeValue The delivery-value floor for a destination kind that spends
     * compose value on the loan chain, in the loan chain's native token. Reserved: every kind V1
     * supports disburses without spending value, so `DESTINATION_KIND_EVM` requires zero and a
     * non-zero floor is refused here, before any bridge fee. It exists in the frozen V1 payload
     * to reduce what enabling a kind that does pay for its own onward delivery has to move -
     * implementations and governed parameters rather than the wire schema. It does not
     * guarantee that: a floor protects delivery funding and settles nothing about quote
     * validity, a spending cap, or an XRPL destination tag, so a kind needing any of those
     * still arrives as a new payload version. Its meaning, once such a kind
     * exists, is the withdraw's: the loan chain refuses any delivery of this borrow - execution
     * and terminal skip alike - carrying less than this, so a front-run with less cannot consume
     * the packet and burn the prepaid value.
     * @param _operationId The user-chosen operation id (non-zero, unique per subaccount).
     * @param _deadline Unix time after which the loan chain skips the instruction unexecuted.
     * Keep it short (under an hour): the loan is priced at the type's fee terms current at
     * delivery, so the front end warns while a terms change is pending in the timelock, and a
     * short deadline is what bounds how far past that warning a delayed packet can execute.
     * @param _extraOptions Caller-supplied LayerZero execution options (type-3).
     */
    function borrow(
        uint256 _collateralAmount,
        uint256 _minCollateralAmount,
        uint256 _borrowAmount,
        uint8 _destinationKind,
        bytes32 _destination,
        uint256 _minComposeValue,
        bytes32 _operationId,
        uint64 _deadline,
        bytes calldata _extraOptions
    )
        external payable;

    /**
     * @notice The deposit-collateral instruction: bridges exactly `_amount` FXRP to this
     * account's own address on the loan chain, with the typed deposit payload the loan-chain
     * twin executes on arrival — supply the bridged amount as collateral, no debt change.
     * @dev Restricted to the parent Personal Account; same guards and fee handling as
     * {borrow}. It carries no operation id and no deadline: a deposit only adds the user's own
     * collateral, which the loan chain's permissionless rail can do with the same tokens
     * anyway, so neither replay protection nor expiry buys anything (the loan-chain action is
     * id-less, like the Flare redeem-home). On the loan chain the deposit is the defensive
     * move: while the controller is paused it still executes when the position carries live
     * debt.
     * @param _amount FXRP to bridge and supply as collateral; non-zero, at most the balance.
     * @param _minAmount The least FXRP that must arrive on the loan chain; non-zero and
     * at most `_amount` - the user's signed allowance for the adapter's fee.
     * @param _extraOptions Caller-supplied LayerZero execution options (type-3).
     */
    function depositCollateral(
        uint256 _amount,
        uint256 _minAmount,
        bytes calldata _extraOptions
    )
        external payable;

    /**
     * @notice The withdraw instruction: a typed, message-only send that atomically withdraws
     * `_amount` of collateral on the loan chain and bridges it home for redemption — no idle
     * window there, so nothing can be redeposited from under it.
     * @dev Restricted to the parent Personal Account; same validation, guards, and fee
     * handling as {borrow}. No FXRP travels with it, but `_options.destinationOptions` must
     * carry, as compose value, the native that prepays the return leg's LayerZero fee (quoted
     * against `_options.returnOptions` on the loan chain, so it includes the redemption's
     * executor fee those options buy; the excess lands on the parent, and too little parks the
     * delivery as retriable). See {WithdrawOptions} for the signed
     * delivery-value floor. A withdrawal that would leave the position under the loan chain's
     * exit gate reverts there (`InsufficientRemainingCollateral`, retriable) until debt and
     * fee are repaid in loan tokens through the subaccount's `repay`, or a smaller amount is
     * signed.
     * @param _amount Collateral to withdraw on the loan chain and bridge home; non-zero.
     * @param _minAmount The least FXRP that must arrive home on the return leg (non-zero, at
     * most `_amount`). The FXRP OFT is fee-capable, and the loan chain quotes the bridge home
     * only when this instruction is delivered - after it was signed - so the floor is named
     * here and carried, never quoted there: a fee raised in between is refused rather than
     * taken out of the user's collateral. Set it to `_amount` when no fee is expected; a fee
     * above the allowance parks the withdrawal (retriable) until a fresh instruction allows it.
     * @param _operationId The user-chosen operation id (non-zero, unique per subaccount).
     * @param _deadline Unix time after which the loan chain skips the instruction unexecuted.
     * @param _options The two option blobs and the delivery-value floor ({WithdrawOptions});
     * `minComposeValue` must be non-zero.
     */
    function withdraw(
        uint256 _amount,
        uint256 _minAmount,
        bytes32 _operationId,
        uint64 _deadline,
        WithdrawOptions calldata _options
    )
        external payable;

    /**
     * @notice The cancel instruction: a message-only send that consumes `_operationId` on the
     * loan chain, so a borrow or withdraw packet carrying that id can never execute.
     * @dev Restricted to the parent Personal Account. The motivating case is a borrow parked by
     * a failed health check after a price drop, which any collateral landing - the user's own
     * deposit or the permissionless rail - would otherwise make executable again. Sending this
     * is not cancellation: the two packets race, an original that lands first executes
     * normally and the cancellation then finalizes silently - so a client resolves a sent
     * cancellation by whichever arrives, the loan chain's
     * {IMorphoLoanSubaccountRemote.LoanActionCancelled} or the original action's own execution event,
     * either of which ends the instruction's live state; and an id a cancellation was signed
     * for is retired for good. It carries no deadline (a late
     * cancellation is unnecessary or still correct). On the loan chain it is not pause-gated;
     * here it travels the ordinary instruction path, which a Flare pause closes like every
     * other instruction (the controller's instruction facets and the bridge send both check
     * it), so a parked packet cannot be revoked from a paused Flare. In that state the loan
     * chain's own pause suspends the borrow but cancels nothing, so the order is: pause the loan
     * chain, restore Flare when safe, submit and confirm the cancellation while the loan chain
     * stays paused, then resume - unpausing it earlier makes the latent packet executable again.
     * Burning an unissued id is allowed and makes a re-send harmless.
     * @param _operationId The operation id to consume; must be non-zero.
     * @param _extraOptions LayerZero options for the cancel message (gas only - it moves no
     * tokens and needs no compose value).
     */
    function cancel(
        bytes32 _operationId,
        bytes calldata _extraOptions
    )
        external payable;

}

contracts/userInterfaces/ISubaccount.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.4 <0.9;

import {IControlledAccount} from "./IControlledAccount.sol";

/**
 * @title ISubaccount
 * @notice The type-generic subaccount surface every implementation must expose. The frozen
 * `SubaccountProxy` creation code embeds `initialize`'s exact selector and delegate-calls
 * it from the proxy constructor, so a new subaccount type is not merely "any contract with a
 * registered implementation": its implementation must implement this interface. Only the
 * initializer's ABI is frozen with the proxy creation code — changing it shifts every predicted
 * subaccount address; the rest of this interface is the protocol's requirement on every
 * implementation, not something the proxy embeds.
 */
interface ISubaccount is IControlledAccount {

    /**
     * @notice Emitted when a subaccount is initialized.
     * @param controllerAddress The controller address.
     * @param parentPersonalAccount The parent Personal Account address (the same address on
     * every chain; codeless on a remote chain until its remote Personal Account is created).
     * @param subaccountType The subaccount type.
     */
    event SubaccountInitialized(
        address indexed controllerAddress,
        address indexed parentPersonalAccount,
        uint256 indexed subaccountType
    );

    /**
     * @notice Reverts if the parent Personal Account address is invalid (zero).
     */
    error InvalidParentPersonalAccount();

    /**
     * @notice Reverts if a parent-driven method is called by anything other than the parent
     * Personal Account (on a remote chain, the remote Personal Account executing the user's
     * signed cross-chain user operation).
     */
    error OnlyParent();

    /**
     * @notice Initializes the subaccount. Delegate-called by the subaccount proxy's
     * constructor; implementations must reject re-initialization and lock the implementation
     * contract itself in their own constructor.
     * @param _controllerAddress MasterAccountController address.
     * @param _parentPersonalAccount Parent Personal Account address.
     * @param _subaccountType The subaccount type.
     */
    function initialize(
        address _controllerAddress,
        address _parentPersonalAccount,
        uint256 _subaccountType
    )
        external;

    /**
     * @notice Returns the parent Personal Account address for this subaccount.
     * @return The parent Personal Account address.
     */
    function parentPersonalAccount()
        external view
        returns (address);

    /**
     * @notice Returns the subaccount type.
     * @return The subaccount type.
     */
    function subaccountType()
        external view
        returns (uint256);

    /**
     * @notice Returns the implementation address of the subaccount.
     * @return The implementation address.
     */
    function implementation()
        external view
        returns (address);
}

contracts/userInterfaces/facets/ICompose.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.4 <0.9;

/**
 * @title IComposeTransportFacet
 * @notice The compose transport of a remote diamond: one record per diamond naming the
 * LayerZero endpoint that may call `lzCompose`, the OFT that must be the compose sender, the
 * origin chain and the pinned peer there. Every compose receiver on the diamond — the remote
 * Personal Account and every remote subaccount type — authenticates against it, so it is the
 * security root of every action that arrives without a local signature. One route per
 * diamond: a token bridged through a different OFT would need a transport per route, which is
 * a schema change, not a setting. Cut only on remote diamonds (the loan chain, Ethereum, at
 * launch).
 * @dev The transport is written under the timelock and cleared immediately: the clear is the
 * containment lever for a compromised endpoint, OFT or peer, and a lever behind a timelock is
 * not one. The clear does not cancel queued `setComposeTransport` calls (the timelock keys them
 * by calldata hash and lets anyone execute a matured one - cancel them first), and it does not
 * retire compose packets already queued at the endpoint (a delivery that reverts against a
 * cleared transport stays retriable). The incident runbook is therefore: pause, cancel queued
 * transport sets, clear, and later set a replacement transport that rotates the compromised
 * identity - the exact compromised tuple is never restored, or packets forged under it would
 * pass authentication again.
 */
interface IComposeTransportFacet {

    /// @dev The compose transport: how authenticated actions arrive and, for the remote loan
    /// subaccount, how the bridge-back leaves. One per diamond, shared by every compose
    /// receiver on it.
    struct Transport {
        /// @notice The LayerZero EndpointV2: the only allowed `lzCompose` caller.
        address lzEndpoint;
        /// @notice The OFT on this chain: the only allowed compose sender (`_from`), the
        /// authoritative identity of the bridged token (`token()`), and the vehicle of the
        /// bridge-back.
        address oft;
        /// @notice The LayerZero endpoint id of the origin chain (Flare).
        uint32 originEid;
        /// @notice The pinned peer on the origin chain (the Flare-side OFT adapter); the
        /// bridge-back re-checks the live peer against it on every call.
        bytes32 originPeer;
    }

    /**
     * @notice Emitted when the compose transport is set.
     * @param lzEndpoint The LayerZero endpoint.
     * @param oft The OFT.
     * @param originEid The origin (Flare) endpoint id.
     * @param originPeer The pinned origin peer.
     */
    event ComposeTransportSet(
        address lzEndpoint,
        address oft,
        uint32 originEid,
        bytes32 originPeer
    );

    /**
     * @notice Emitted when the compose transport is cleared.
     */
    event ComposeTransportCleared();

    /**
     * @notice Reverts if the LayerZero endpoint is not a contract, or is not the endpoint the
     * OFT is wired to.
     */
    error InvalidLzEndpoint();

    /**
     * @notice Reverts if the origin endpoint id is zero.
     */
    error InvalidOriginEid();

    /**
     * @notice Reverts if the origin peer is zero, has dirty upper bits (not a clean
     * zero-padded EVM address), or does not match the OFT's live peer for the origin endpoint.
     */
    error InvalidOriginPeer();

    /**
     * @notice Reverts if the OFT is not a contract, its shared decimals differ from its own
     * token's, it reports a non-canonical interface/message-codec version, or - once a token
     * is pinned - it wraps a different token.
     */
    error InvalidOft();

    /**
     * @notice Reverts when an operation needs the compose transport and it is not configured.
     */
    error ComposeTransportNotConfigured();

    /**
     * @notice Returns the compose transport.
     * @return The transport; all-zero when not configured.
     */
    function getComposeTransport()
        external view
        returns (Transport memory);
}

contracts/userInterfaces/facets/IMorphoL.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.4 <0.9;

import {IMorpho} from "../../smartAccounts/interface/IMorpho.sol";

/// @dev The maximum fee floor and fee spread: annual WAD rates (`1e18` = 100% per year), each
/// capped at 100%. The cap bounds the accrual arithmetic for every rate an account can ever
/// snapshot - a bad stored rate could not be repaired by changing the global terms, since an
/// account always prices its elapsed period at the terms it snapshotted.
uint64 constant MAX_FEE_RATE = 1e18;

/**
 * @title IMorphoLoanMarketsFacet
 * @notice Governance-set per-type configuration of the remote loan subaccounts: a write-once
 * Morpho market (a position's market can never change under it, so exits need no registry; a
 * new pool is a new subaccount type), a mutable borrow switch — the routine way to sunset a
 * pool — and mutable Flare fee terms. Registration pins the collateral token to the transport
 * OFT's token, for that market and every later transport; the first non-zero fee recipient
 * activates borrowing. Cut only on the loan-chain diamond (Ethereum, at launch).
 */
interface IMorphoLoanMarketsFacet {

    /// @dev The pool a subaccount type is bound to: a Morpho contract and a market on it.
    /// Write-once per type - positions live in it, so the binding must never change.
    struct Market {
        /// @notice The Morpho contract.
        address morpho;
        /// @notice The Morpho market on it. `collateralToken` must be the transport OFT's
        /// token (enforced); the loan token is RLUSD by governance policy per registration,
        /// not an on-chain check.
        IMorpho.MarketParams marketParams;
    }

    /// @dev A subaccount type's Flare fee terms: the user's effective rate is
    /// `max(feeFloor, market interest rate + feeSpread)`, measured checkpoint-to-checkpoint
    /// by the subaccounts. Set as one unit by timelock after registration, and changed the
    /// same way (accounts snapshot the terms they accrue under, so a change is never
    /// retroactive). Explicit zero rates are a deliberate "fee off".
    struct FeeTerms {
        /// @notice The minimum effective annual rate (WAD, at most {MAX_FEE_RATE}).
        uint64 feeFloor;
        /// @notice The annual spread over the market's rate (WAD, at most {MAX_FEE_RATE}).
        uint64 feeSpread;
        /// @notice The collector the fee is paid to. Zero exactly while the type's terms are
        /// unconfigured - the activation marker: borrowing reverts until the terms are set,
        /// and the setter never accepts zero, so it can never return to zero. Rotating it
        /// changes where the fee goes, not what anyone owes.
        address feeRecipient;
    }

    /**
     * @notice Emitted when a subaccount type's market is registered (write-once).
     * @param subaccountType The subaccount type the market is bound to.
     * @param morpho The Morpho contract.
     * @param marketId The Morpho market id: `keccak256(abi.encode(marketParams))`.
     */
    event LoanMarketRegistered(
        uint256 indexed subaccountType,
        address morpho,
        bytes32 marketId
    );

    /**
     * @notice Emitted when new debt increases are disabled for a subaccount type.
     * @param subaccountType The subaccount type.
     */
    event LoanBorrowingDisabled(
        uint256 indexed subaccountType
    );

    /**
     * @notice Emitted when new debt increases are re-enabled for a subaccount type.
     * @param subaccountType The subaccount type.
     */
    event LoanBorrowingEnabled(
        uint256 indexed subaccountType
    );

    /**
     * @notice Emitted on every timelocked fee-terms set: the activating configuration and
     * every later rate change or recipient rotation.
     * @param subaccountType The subaccount type.
     * @param feeFloor The minimum effective annual rate (WAD).
     * @param feeSpread The annual spread over the market's rate (WAD).
     * @param feeRecipient The collector the fee is paid to.
     */
    event LoanFeeTermsSet(
        uint256 indexed subaccountType,
        uint64 feeFloor,
        uint64 feeSpread,
        address feeRecipient
    );

    /**
     * @notice Reverts if the Morpho address is invalid.
     */
    error InvalidMorpho();

    /**
     * @notice Reverts if the Morpho market parameters are invalid: a zero or codeless token,
     * a codeless oracle, identical tokens, a zero LLTV, a collateral token other than the
     * transport OFT's token, or a market that does not exist on the Morpho contract.
     */
    error InvalidMarketParams();

    /**
     * @notice Reverts on registering a market for a type that already has one: the binding
     * is write-once - a different market means a new subaccount type.
     * @param subaccountType The already-bound subaccount type.
     */
    error MarketAlreadyRegistered(
        uint256 subaccountType
    );

    /**
     * @notice Reverts when an operation needs a type's market and none is registered.
     * @param subaccountType The subaccount type without a market.
     */
    error MarketNotRegistered(
        uint256 subaccountType
    );

    /**
     * @notice Reverts on a fee floor or fee spread above {MAX_FEE_RATE}.
     */
    error InvalidFeeTerms();

    /**
     * @notice Reverts on a zero fee recipient: the terms must always name a collector, even
     * with both rates deliberately zero.
     */
    error InvalidFeeRecipient();

    /**
     * @notice Returns the market a subaccount type is bound to.
     * @param _subaccountType The subaccount type.
     * @return The market; a zero `morpho` means no market is registered for the type.
     */
    function getLoanMarket(
        uint256 _subaccountType
    )
        external view
        returns (Market memory);

    /**
     * @notice Returns whether new debt increases are disabled for a subaccount type.
     * Repayment, collateral deposits, withdrawals, and recovery are never affected.
     * @param _subaccountType The subaccount type.
     * @return Whether borrowing is disabled.
     */
    function isLoanBorrowingDisabled(
        uint256 _subaccountType
    )
        external view
        returns (bool);

    /**
     * @notice Returns a subaccount type's Flare fee terms.
     * @param _subaccountType The subaccount type.
     * @return The fee terms; a zero `feeRecipient` means the type's terms are not yet
     * configured, and borrowing reverts until they are.
     */
    function getLoanFeeTerms(
        uint256 _subaccountType
    )
        external view
        returns (FeeTerms memory);
}

contracts/userInterfaces/facets/IPauseFa.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.4 <0.9;

/**
 * @title IPauseFacet
 * @notice Interface for the PauseFacet contract.
 */
interface IPauseFacet {

    /**
     * @notice Emitted when the contract is paused.
     * @param account The account that triggered the pause.
     */
    event Paused(address indexed account);

    /**
     * @notice Emitted when the contract is unpaused.
     * @param account The account that triggered the unpause.
     */
    event Unpaused(address indexed account);

    /**
     * @notice Emitted when a pauser is added.
     * @param account The pauser address.
     */
    event PauserAdded(address indexed account);

    /**
     * @notice Emitted when a pauser is removed.
     * @param account The pauser address.
     */
    event PauserRemoved(address indexed account);

    /**
     * @notice Emitted when an unpauser is added.
     * @param account The unpauser address.
     */
    event UnpauserAdded(address indexed account);

    /**
     * @notice Emitted when an unpauser is removed.
     * @param account The unpauser address.
     */
    event UnpauserRemoved(address indexed account);

    /**
     * @notice Reverts if the contract is paused.
     */
    error IsPaused();

    /**
     * @notice Reverts if the caller is not a pauser.
     * @param account The caller address.
     */
    error NotPauser(address account);

    /**
     * @notice Reverts if the caller is not an unpauser.
     * @param account The caller address.
     */
    error NotUnpauser(address account);

    /**
     * @notice Reverts if the address is already a pauser.
     * @param account The address.
     */
    error PauserAlreadyAdded(address account);

    /**
     * @notice Reverts if the address is already an unpauser.
     * @param account The address.
     */
    error UnpauserAlreadyAdded(address account);

    /**
     * @notice Pause the contract. Only callable by pausers.
     */
    function pause() external;

    /**
     * @notice Unpause the contract. Only callable by unpausers.
     */
    function unpause() external;

    /**
     * @notice Returns whether the contract is paused.
     * @return True if paused, false otherwise.
     */
    function isPaused() external view returns (bool);

    /**
     * @notice Returns whether an address is a pauser.
     * @param _account The address to check.
     * @return True if the address is a pauser.
     */
    function isPauser(address _account) external view returns (bool);

    /**
     * @notice Returns whether an address is an unpauser.
     * @param _account The address to check.
     * @return True if the address is an unpauser.
     */
    function isUnpauser(address _account) external view returns (bool);

    /**
     * @notice Returns all pauser addresses.
     * @return The list of pausers.
     */
    function getPausers() external view returns (address[] memory);

    /**
     * @notice Returns all unpauser addresses.
     * @return The list of unpausers.
     */
    function getUnpausers() external view returns (address[] memory);
}

contracts/userInterfaces/facets/ISubacco.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.4 <0.9;

/// @dev Reserved subaccount type: "not configured". Never has an implementation. Every other
/// value is an allocation this deployment made, not a protocol concept: the ids in use are in
/// `deployment/lib/SubaccountTypes.sol` and published in `docs/specs/ApiReference.md`.
uint256 constant SUBACCOUNT_TYPE_NONE = 0;

/**
 * @title ISubaccountsFacet
 * @notice Interface for the SubaccountsFacet contract: the type registry and creation route
 * shared by every subaccount type. The controller (Diamond) is the beacon for subaccounts; a
 * proxy resolves its implementation through {implementationForType} using its fixed type.
 * @dev The subaccount type is a raw `uint256` rather than an enum on purpose: the proxy creation
 * code - and with it the type's encoding in the constructor arguments and the initializer call -
 * is frozen for deterministic CREATE2 addresses, and a compiled enum
 * decoder rejects values outside the range it was compiled with, which would make future type
 * values undeployable through the frozen artifact. Type `0` is reserved and invalid; any other
 * value is usable once governance registers an implementation for it.
 */
interface ISubaccountsFacet {

    /**
     * @notice Emitted when the subaccount implementation is set for a type.
     * @param subaccountType The subaccount type.
     * @param implementation The implementation address set for the type.
     */
    event SubaccountImplementationSet(
        uint256 indexed subaccountType,
        address implementation
    );

    /**
     * @notice Emitted when a new subaccount is created.
     * @param subaccount The deployed subaccount contract address.
     * @param parentPersonalAccount The parent Personal Account address.
     * @param subaccountType The subaccount type.
     */
    event SubaccountCreated(
        address indexed subaccount,
        address indexed parentPersonalAccount,
        uint256 indexed subaccountType
    );

    /**
     * @notice Reverts if the subaccount implementation address is invalid.
     */
    error InvalidSubaccountImplementation();

    /**
     * @notice Reverts if the subaccount type is invalid (the reserved type `0`).
     */
    error InvalidSubaccountType();

    /**
     * @notice Reverts if no implementation is configured for the subaccount type.
     * @param subaccountType The subaccount type without an implementation.
     */
    error SubaccountImplementationNotSet(
        uint256 subaccountType
    );

    /**
     * @notice Reverts if the subaccount was not successfully deployed.
     * @param subaccountAddress The address of the subaccount.
     */
    error SubaccountNotSuccessfullyDeployed(
        address subaccountAddress
    );

    /**
     * @notice Creates the subaccount for an XRPL owner if it does not exist yet.
     * @dev Permissionless, idempotent and not pause-gated, as `createPersonalAccount` is. An
     * executor uses it to materialize a subaccount whose predicted address already received
     * assets, so that they can be swept; a user operation uses it as its first call, before
     * calling a method on the subaccount. The parent Personal Account is created along with it
     * when it does not exist yet, on every chain: a codeless parent leaves the account with no
     * caller and no way home on Flare, and on a remote chain leaves what the compose rails push
     * to it spendable by no one. Nothing can create it from the subaccount afterwards, which
     * holds its address while the deployment is keyed by the owner string. Requires a
     * registered implementation for the type and for the Personal Account.
     * @param _xrplOwner The XRPL address of the owner.
     * @param _subaccountType The subaccount type.
     * @return The subaccount contract address.
     */
    function createSubaccount(
        string calldata _xrplOwner,
        uint256 _subaccountType
    )
        external
        returns (address);

    /**
     * @notice Get the subaccount for a given XRPL owner and subaccount type.
     * @param _xrplOwner The XRPL address of the owner.
     * @param _subaccountType The subaccount type.
     * @return The subaccount address associated with the XRPL owner
     * or the computed address if not yet deployed.
     */
    function getSubaccount(
        string calldata _xrplOwner,
        uint256 _subaccountType
    )
        external view
        returns (address);

    /**
     * @notice Returns the implementation address for a given subaccount type.
     * @dev The frozen subaccount proxy creation code embeds this exact selector: renaming it
     * shifts every predicted subaccount address (a refreeze, only possible before the first
     * deployment).
     * @param _subaccountType The subaccount type to resolve.
     * @return The implementation address, or the zero address if not configured.
     */
    function implementationForType(
        uint256 _subaccountType
    )
        external view
        returns (address);
}

